programs.haiku:
"""Speech-introducer feature: fires on the token just before a quotation, a reported
statement or an explanation is about to start, e.g. the colon in 'Mallya said:' or the
comma in 'it says, ...' or 'I thought, ...'. Also dips negative on the first token of
each document."""
READS = ()

SPEECH_WORDS = {"say", "says", "said", "saying", "states", "stated", "thought", "thinking",
                "think", "wrote", "writes", "asked", "claims", "claimed", "declared", "replied",
                "answered", "told", "question", "believe", "argues", "like"}
COLONS = {":", "：", ":\n", ":\n\n", ":\n\n\n", ":\\", "：“", " :"}
COMMAS = {",", "，"}
QUOTES = {" \"", " “", "“", " «", " „"}
WINDOW = 2
DOC_START = -0.42

def step(carry, prefix, upstream):
    if prefix.position == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        return 99, DOC_START
    since = carry
    tok = prefix.token_strings[-1]
    near = since <= WINDOW
    if tok in COLONS:
        value = 2.0 if near else (0.55 if '\n' in tok else 0.3)
    elif tok in COMMAS:
        value = 1.2 if near else 0.0
    elif tok in QUOTES:
        value = 1.0 if near else 0.2
    elif tok.strip().lower() in SPEECH_WORDS:
        value = 0.5
    else:
        value = 0.0
    since = 0 if tok.strip().lower() in SPEECH_WORDS else since + 1
    return since, value

programs.sol:
"""A sparse lexical contrast, mostly Go/build spellings versus JavaScript.

Source-code syntax gates English homographs such as 'make', 'go', 'now',
and 'function'. Stronger rules recognize allocation with :=, std::,
Golang, and a few file/serialization conventions. Repeated middle-dot
punctuation has a positive rule; document starts get a 0.22 offset. Other
tokens stay near zero. Only 600 characters of the current document persist;
this is not a general programming-language classifier.
"""
import re

READS = ()
CODE = re.compile(r'[{};=`]|::|:=|\w[._/]\w|\\[nt]|\n[ \t]{2,}')
TAGS = re.compile(r'<\|[^>]*\|>|</?tool_[^>]*>')


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    past = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    word = token.strip()
    bare = word.lstrip('.(/"\'`_=-')
    new_carry = (doc, (past + token)[-600:])
    value = 0.0

    # Fixed spellings of language, package, and file-format conventions.
    if word == '.go':
        value = -1.2
    elif bare == 'olang' and past.lower().endswith('g'):
        value = -3.8
    elif bare == 'fmt':
        value = -0.9 if token.startswith('\t') else -1.4
    elif bare == 'func':
        value = -0.75
    elif word == '::' and re.search(r'\bstd\s*$', past):
        value = -1.6
    elif word == '.js':
        value = 0.55
    elif bare == 'ignore' and past.lower().endswith('git'):
        value = -1.0
    elif bare == 'file' and past.lower().endswith('make'):
        value = -0.5
    elif bare == 'node' and word.startswith(('/', '-')):
        value = -0.9
    elif bare in {'cargo', 'npm'}:
        value = -0.5
    elif bare.lower() == 'formatter' or word == '.stringify':
        value = -0.75
    elif word == '.dumps':
        value = -2.0
    elif bare == 'finally' and past.rstrip().endswith('}'):
        value = 1.0
    elif ((bare == 'Compose' and 'Docker' in past[-40:]) or
          (bare == 'pose' and past.endswith('Com'))):
        value = -5.0
    elif token == '··' and past.endswith('··'):
        value = 1.22
    elif (bare in {'make', 'Make', 'go', 'now', 'Now', 'NOW',
                   'js', 'auto', 'my'} or bare.lower() == 'function'):
        # Recent punctuation/indentation, not the model's hidden state.
        code = bool(CODE.search(TAGS.sub('', past[-160:])))
        chat = '<|im_start|>' in past or '</tool_' in past
        if bare in {'make', 'Make'}:
            value = -1.7 if code else -0.35 if chat else 0.0
            identifier = (word.startswith(('.', '(')) or
                          re.search(r'(?:[._/`]|::|:=|\bdef)\s*$', past) or
                          (code and re.search(r'\n\s*$', past)))
            if identifier:
                value -= 1.35
            if bare == 'Make' and code:
                value -= 1.2
            if not token.startswith(' '):
                value -= 0.5
            if re.search(r':=\s*$', past):
                value = -5.6  # Go's make allocation builtin.
        elif bare == 'go':
            value = -1.2 if code else -0.2 if chat else -0.08
            if word.startswith(('/', '-')):
                value = -1.4
        elif bare in {'now', 'Now', 'NOW'}:
            value = -0.6 if code else -0.45 if chat else -0.12
            if word.startswith('.'):
                value = -2.7
        elif bare.lower() == 'function':
            value = 0.2 if code else 0.15 if chat else -0.12
            if not token.startswith(' '):
                value += 0.35
            if re.search(r'(?:\basync|[,({:=]|\n[ \t]*)\s*$', past):
                value += 0.55
        elif bare == 'js':
            value = 0.75 if code else 0.3
            if re.search(r'[/\.][cm]$', past):
                value += 2.0  # cjs/mjs module-format suffixes.
        elif bare == 'auto':
            value = -0.8 if code else -0.05
            if token.startswith('\t'):
                value = -2.0
        elif bare == 'my' and not token.startswith(' ') and code:
            value = -1.2

    # A small start-of-document offset, independently of the lexical cues.
    if not past:
        value += 0.22
    return new_carry, float(value)

programs.haiku:
"""Programming-language token detector for one residual direction.

Negative on Go-language words (.go, go.mod, fmt, func, golang) and on Go's `make` builtin
(strongest when `make` starts an assignment, `x := make(...)`); the Go words are stronger
once the text so far looks like Go code. Mildly negative on C++ `std::` and on a few build/tool
words; positive on JavaScript words (js, .js, function, module), and on runs of middle dots
(leader dots). Everything else, including ordinary English (e.g. "to make sure"), is about zero.
"""
READS = ()

ASSIGN = {"=", ":=", " =", " :="}
MAKE = {"make", " make", "Make", " Make", ".make", "ake"}
GO = {".go", "go", " go", "-go", "/go", "olang", "fmt", " fmt", "\tfmt", "func", " func", "\tfunc"}
GO_CUE = GO | MAKE | {":=", "package", "err", "nil"}
NODE = {"/node", "-node", "ignore"}
JS = {"js", ".js", " js", "function", " function", "\tfunction", "(function", "typeof", "module",
      "Function", "javascript", " JS", "FUNCTION"}
STD = {"std", " std", "\tstd", "(std"}


def step(carry, prefix, upstream):
    t = prefix.token_strings[-1]
    prev = prefix.token_strings[-2] if prefix.position > 0 else ""
    new_doc = prefix.position == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]
    cues = 0 if (carry is None or new_doc) else carry
    if t in GO_CUE:
        cues += 1
    code = min(cues, 3) / 3.0          # 0 in prose, 1 once the text looks like Go
    if t in MAKE:
        return cues, (-5.5 if prev in ASSIGN else -0.6 * (0.5 + code))
    if t in GO:
        return cues, -1.1 * (0.5 + code)
    if t == "::" and prev in STD:
        return cues, -1.7
    if t in NODE:
        return cues, -0.9
    if t in JS:
        return cues, 0.5
    if len(t) >= 2 and set(t) == {"·"}:
        return cues, 1.2
    return cues, 0.0

programs.sol:
"""Hen/chicken words and their spelling echoes.

Large positives mark chicken/hen words (also Chinese chicken), Chen-like
syllables, and especially EN/ENS completing a preceding H. Chinese Chen
characters and several small hen-like fragments get moderate positives. Some split
HI spellings, notably CH+IR/IM/IED, have the opposite sign. Common complete
words such as 'when', 'then', and 'Henry' do not receive a hen bonus.
Repeated two-middle-dot tokens get a small negative value. Only the preceding
token is retained, and documents reset that state.
"""
import regex as re
from opencc import OpenCC

READS = ()
_SIMPLIFY = OpenCC('t2s')


def value(s, previous):
    w = s.strip().lower()
    p = previous.lower()
    if w in ('chicken', 'chickens'):
        return 5.8 if w == 'chicken' else 4.4
    if w in ('chick', 'chicks'):
        return 4.0
    if re.search(r'\p{Script=Han}', w):
        simplified = _SIMPLIFY.convert(w)
        if simplified == '鸡':
            return 6.8
        if simplified == '陈':
            return 2.35
        return -0.002
    if w == '··' and previous.strip() == w:
        return -0.9

    attached = bool(s) and not s[0].isspace()
    beginning = not attached or not p or not p[-1].isalpha()
    if re.fullmatch(r'[cs]?hen', w):
        if beginning:
            return 6.9 if w == 'hen' else 5.2
        if w == 'hen':
            return 0.7 if p[-1:] in 'aeiouy' else 1.9
        return 1.3
    if w == 'phen':
        return 1.6
    if w.endswith('ohen') and len(w) <= 5:
        return 1.8
    if w in ('hick', 'hicks'):
        return 3.5
    if re.fullmatch(r'[cs]?hi(?:r|ed|m)', w):
        return -1.0

    if attached and p.endswith('h'):
        if w in ('en', 'ens'):
            if len(p.strip()) > 3:
                return 1.6
            if p.strip() in ('h', 'ch', 'sh', 'ph'):
                return 7.8
            return 3.8
        if w == 'end':
            return 2.5
        if w in ('enan', 'ene'):
            return 3.5
        if w.startswith('en') and not w.startswith(('ence', 'ent')):
            return 0.6
        if w.startswith('i'):
            if w.startswith('icken'):
                return 3.0
            if w in ('ick', 'icks'):
                return 6.2 if p.strip() == 'h' else 3.5
            if w == 'in':
                return 0.6
            if re.fullmatch(r'i(?:r|ed|d|me?s?|mp)', w):
                strong = p.strip() == 'ch' or p.endswith(('sch', 'eh'))
                return -3.2 if strong else -0.8
            if p.endswith(('ch', 'sh')):
                if w == 'ing' and p.strip() in ('ch', 'sch'):
                    return -2.0
                if w.startswith(('ir', 'ip', 'is', 'iz', 'iu')):
                    return -1.3
        if w == 'n':
            return 0.55
    return -0.002


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == document else ''
    s = prefix.token_strings[-1]
    return (document, s), float(value(s, previous))

"""Predict from token spelling and whether the document has just begun.

Opening capitals tend negative; leading spaces and code continuations tend
positive. A few recognizable opening forms have larger values. Word length,
case, script and English frequency supply small baselines elsewhere.
Repeated copies of the opening token retain the opening treatment.
This is a partial approximation, not a token-by-token lexical model.
"""
import regex
from wordfreq import zipf_frequency

READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    token_id = prefix.token_ids[-1]
    if carry is None or carry[0] != doc:
        opening = True
        first_id = token_id
    else:
        _, first_id, opening = carry
        opening = opening and token_id == first_id

    text = token.strip()
    if opening:
        if token == "<!":
            value = 2.43
        elif token == "bool":
            value = 1.57
        elif token == "\\t":
            value = 0.86
        elif text and set(text) == {"^"} and len(text) > 1:
            value = 1.41
        elif token == "\t":
            value = 0.56
        elif not text:
            value = 0.12 if "\n" in token else 0.18
        elif token.startswith(" "):
            value = 0.14
        elif token.startswith("<|"):
            value = -0.22
        elif token.startswith("#") or token == "//":
            value = -0.33
        elif token[0].isupper():
            common = zipf_frequency(text.lower(), "en") >= 5
            if len(text) == 1:
                value = -0.30
            else:
                value = -0.38 if common else -0.26
        elif token.isdigit():
            value = -0.16
        elif regex.search(r"\p{Script=Han}", token):
            value = -0.03
        elif token[0].islower():
            frequency = zipf_frequency(text, "en")
            if len(text) == 1:
                value = -0.30 if frequency >= 3 else 0.15
            elif len(text) <= 3:
                value = -0.03 if frequency >= 5 else 0.12
            else:
                value = -0.18 if frequency >= 3 else 0.05
        elif len(token) > 1 and token[0] == "." and token[1].isalpha():
            value = 0.65
        elif token.startswith("_"):
            value = 0.35
        elif token.startswith(("'", '"')):
            value = -0.10
        else:
            value = 0.10
    elif not text:
        value = -0.001 if "\n" in token else 0.001
    elif token.isdigit():
        value = 0.0
    elif token[0].islower():
        value = 0.019 if len(text) > 3 else 0.008
    elif regex.search(r"\p{Script=Han}", token):
        value = 0.010
    elif token[0].isupper():
        frequency = zipf_frequency(text.lower(), "en")
        if frequency >= 5:
            value = 0.002
        elif frequency >= 3:
            value = 0.008
        else:
            value = 0.020
    else:
        value = 0.005
    return (doc, first_id, opening), value

programs.haiku:
"""Layer-1 MLP down_proj component 1030, a first-token and middle-dot detector.

Almost always near zero. It responds in two places:
  * the first token of each document (a packed row starts documents after
    <|endoftext|>, and the document id changes there). The value depends on the
    kind of token that opens the document: a capitalised word such as "The" or
    "In" pushes it clearly negative; digits and special markup such as <|im_start|>
    push it negative; a word with a leading space pushes it positive; other
    symbols and lowercase words sit slightly positive or near zero.
  * the middle-dot token "··" (U+00B7, as in leader dots or ornaments), which gives
    a large, steady positive value wherever it appears.
Everywhere else it predicts 0.
"""

READS = ()

DOT_TOKEN = "··"


def _first_token_value(s):
    body = s.strip()
    if body.isdigit() or (s.startswith("<") and s.endswith(">")):
        return -0.19
    if s[:1].isupper():
        return -0.32
    if s.startswith(" ") and body.isalpha():
        return 0.14
    if s.isalpha():
        return -0.04
    return 0.08


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    if s == DOT_TOKEN:
        return None, 0.8
    docs = prefix.document_ids
    if len(docs) == 1 or docs[-1] != docs[-2]:
        return None, _first_token_value(s)
    return None, (0.012 if s.isalpha() else 0.0)

programs.sol:
"""Approximate a token-form and rarity signal, rather than memorizing tokens.

Use broad classes: English frequency, letters versus punctuation, unfinished
UTF-8, quotes, delimiters, and indentation. Add small case/length corrections.
Document starts receive a negative adjustment; a weak early-position boost
then decays. These rules leave individual-word preferences unexplained.
"""
import math

READS = ()

from functools import lru_cache
from wordfreq import zipf_frequency

def token_base(b):
    s = b.decode('utf-8', 'replace')
    w = s.strip()
    if '\ufffd' in w:
        return (0.925 if 0x80 <= b[0] <= 0xbf else 1.358)
    if not w:
        if not s.strip('\t'):
            return 0.975  # tabs
        if not s.strip('\xa0'):
            return 0.911  # nonbreaking spaces
        if not s.strip('\r\n'):
            return -0.078  # linebreaks
        if s == '    ':
            return 0.716  # four space indent
        return 0.069  # other whitespace
    if w.isdigit():
        return 0.087  # digits
    if s == '<|im_start|>':
        return 1.009  # turn start
    if s.startswith('<|') and s.endswith('|>'):
        return -0.066  # other boundary markers
    if not any(c.isalnum() for c in w):
        if any(c in w for c in "'\""):
            return 0.969 if s.startswith(' ') else 0.356
        if '`' in w:
            return 0.066 if s.startswith(' ') else 0.561
        if ']' in w:
            return 0.775  # closing square bracket
        if '}' in w:
            return 0.641  # closing brace
        if '(' in w or '[' in w or '{' in w:
            return 0.385  # opening delimiter
        if any(c in w for c in '/\\'):
            return 0.372  # slash
        if any(c in w for c in '+*=<>%&|^~'):
            return 0.243  # operator
        if '、' in w or '：' in w:
            return 0.999  # cjk separator
        if any(c in w for c in '!?'):
            return 0.261  # question exclamation
        return 0.110  # other punctuation
    if w.isascii() and w.isalpha():
        if w.lower() == 'from':
            return 0.845  # source preposition
        f = zipf_frequency(w.lower(), 'en')
        if f == 0:
            return 0.388  # unlisted english piece
        if f <= 2:
            return 0.398  # very rare english piece
        if f <= 3:
            return 0.421  # rare english piece
        if f <= 4:
            return 0.282  # uncommon english piece
        if f <= 5:
            return 0.154  # medium frequency english
        if f <= 6:
            return 0.084  # frequent english
        return -0.008  # very frequent english
    if w.isalpha():
        return 0.433  # non ascii letters
    return 0.241  # mixed text and symbols


@lru_cache(maxsize=32768)
def token_value(b):
    word = b.decode('utf-8', 'replace').strip()
    return (token_base(b) + 0.076 * word.istitle()
            + 0.096 * word.isupper() - 0.099 * (len(word) == 1))


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    position = 0 if carry is None or carry[0] != doc else carry[1] + 1
    b = prefix.token_bytes[-1]
    s = b.decode('utf-8', 'replace')
    word = s.strip()
    value = token_value(b)
    if position == 0:
        # Boundary markers have distinct no-context values.
        if s == '<|endoftext|>':
            value = -6.900
        elif s == '<|im_start|>':
            value = -1.345
        elif s == '<|im_end|>':
            value = -1.976
        else:
            value -= 1.795
            value += 0.846 * (bool(word) and not any(c.isalnum() for c in word))
            value += 0.395 * ('\n' in s)
            value += 0.567 * word.isdigit()
    else:
        value += 0.135 * math.exp(-position / 20)
    return (doc, position), float(value)

programs.haiku:
"""Activation of layers.1.mlp.down_proj:1031 (one rank-one piece of the layer-1 MLP
down projection), predicted from the current token and where it sits in its document.

What it does, in plain terms:
- The first token of a document has no context, and the component is strongly negative
  there (about -1.5). This is the one large, clean effect.
- Otherwise it is mostly positive on a few kinds of token:
  * a broken UTF-8 byte piece (decodes to U+FFFD): about +1;
  * quotation marks, brackets, backslashes, tabs, non-breaking spaces and 4-space
    indents (code and markup punctuation): about +0.5;
  * CJK characters and other non-ASCII symbols: about +0.1 to +0.4;
  * word fragments: letters with no leading space, a word that started earlier: about +0.27;
  * whole words with a leading space: about +0.12; other punctuation about +0.15;
  * digits and bare spaces: about 0.
The values are the class means measured on training text. The program cannot see the next
token, so it does not model the "word continues" effect directly; it is a token-class
summary and explains only a small share of the variance, well short of a per-token table.
"""

import unicodedata

READS = ()

CODE_TOKENS = {'"', "'", "]", "[", "\\", "|", "(", "{", '\t', '\xa0', '    ', ' "', " '",
               ' [', ' \\', ' |', ' (', ' {'}


def _is_cjk(s):
    return any("CJK" in unicodedata.name(ch, "") for ch in s)


def _value(s):
    t = s.strip()
    if "�" in s:
        return 1.0
    if _is_cjk(s):
        return 0.4
    if s in CODE_TOKENS:
        return 0.5
    if any(ord(ch) > 127 for ch in s) and not t.isalpha():
        return 0.1
    if t.isdigit():
        return 0.0
    if t.isalpha() and not s.startswith(" "):
        return 0.27
    if t.isalpha():
        return 0.12
    if t == "":
        return 0.04
    return 0.15


def step(carry, prefix, upstream):
    doc_start = prefix.position == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]
    if doc_start:
        return carry, -1.5
    return carry, float(_value(prefix.token_strings[-1]))

programs.sol:
"""Approximate a source-code module-loading feature using readable syntax rules.

Bare source-string openings in JavaScript imports and require calls get the
largest values; merged relative-path prefixes get smaller ones. Separate
rules cover Python imports, Go blocks, Rust paths and C++ includes. Values
are training-set averages, not a parser or a table of library names. Most
ordinary text is zero; document starts and test-log PASS have small baselines.
The state holds 600 recent characters and a Go-block flag, reset between
documents. Individual library-name effects are not modeled.
"""
import re
import sys

READS = ()

# ECMAScript module clauses: a default name, braces, or a star import.
JS_CLAUSE = re.compile(
    r'\b(?:import|export)\s+(?:type\s+)?'
    r'(?:[\w$]+(?:\s*,\s*)?)?'
    r'(?:\{[^{};]*\}|\*(?:\s+as\s+[\w$]+)?)?\s*$')

SOURCE_OPENINGS = {
    'js_from_bare': 13.09,
    'node_require_bare': 10.43,
    'go_bare': 4.02,
    'js_from_parent': 5.71,
    'js_from_scoped': 7.56,
    'js_from_local': 3.33,
    'ruby_require_bare': 4.75,
    'node_require_local': 3.68,
    'node_require_parent': 5.87,
    'js_from_absolute': 8.86,
    'direct_import_bare': 9.89,
    'encoded_require_bare': 3.04,
    'node_require_scoped': 5.51,
    'direct_import_local': 3.03,
}


def normalized(s):
    return (s.replace('\\\\', '\\').replace('\\n', '\n')
            .replace('\\t', '\t').replace('\\r', '\r'))


def activation(carry, s, doc):
    if carry is None or carry[0] != doc:
        carry = (doc, '', False)
    _, raw, go = carry
    before = normalized(raw)
    line = before.rsplit('\n', 1)[-1]
    token = normalized(s)
    word = token.strip()
    tail = before.rstrip()
    # Opening a Go block also covers source printed with line numbers.
    direct = tail.endswith('import')
    opening_go = direct and token.lstrip().startswith('(')
    new_go = (go or opening_go) and not token.lstrip().startswith(')')
    new = (doc, (raw + s)[-600:], new_go)
    if not raw:
        if word in ('import', 'use', '#include', '#pragma'):
            return new, -1.4
        return new, 0.22

    # Identify the opening delimiter, including path prefixes merged into it.
    quote = re.match(r'''\s*\(?[\\]*['"]''', token)
    include = tail.endswith('include') and bool(
        re.search(r'#\s*include$', tail[-30:]))
    es_from = tail.endswith('from') and bool(
        JS_CLAUSE.search(tail[-500:-4]))
    require = bool(re.search(r'\brequire(?:_relative)?\s*\(?$', tail[-35:]))
    go_open = go and bool(re.fullmatch(
        r'\s*(?:\d+[:\t ]+)?[.\w]*\s*', line))
    if include and token.lstrip().startswith('<'):
        return new, 2.93
    if quote:
        path = token[quote.end():]
        if include:
            return new, 2.45
        if es_from or require or direct or go_open:
            if es_from:
                kind = 'js_from'
            elif require:
                if '\\' in s:
                    kind = 'encoded_require'
                elif '(' in token or tail.endswith('('):
                    kind = 'node_require'
                else:
                    kind = 'ruby_require'
            elif go_open:
                kind = 'go'
            else:
                kind = 'direct_import'
            if kind != 'go':
                if path.startswith('../'):
                    form = 'parent'
                elif path.startswith('./'):
                    form = 'local'
                elif path.startswith('@'):
                    form = 'scoped'
                elif path.startswith('/'):
                    form = 'absolute'
                else:
                    form = 'bare'
            else:
                form = 'bare'
            key = kind + '_' + form
            if kind == 'encoded_require':
                return new, SOURCE_OPENINGS.get(key, 3.0)
            if kind == 'ruby_require':
                return new, SOURCE_OPENINGS.get(key, 4.75)
            return new, SOURCE_OPENINGS.get(key, 0.0)

    if word in ('require', '(require'):
        if (re.search(r'[=(,]\s*$', tail) and
                not re.search(r'[A-Za-z]\s+[A-Za-z]+,\s*$', tail)):
            return new, 5.8
        return new, 0.05
    if word == 'from' and line.strip() and JS_CLAUSE.search(before[-500:]):
        return new, 3.07
    if word == 'import':
        if re.search(r'\bfrom\s+[.\w]+\s*$', line):
            return new, 0.99
        if ';' in before[-200:]:
            return new, 0.1
        if re.search(r'\bimport\s+[^\n;]+\n', before[-200:]):
            return new, 0.92
        return new, 0.18
    if opening_go:
        return new, 0.63
    if word == '#include':
        return new, 1.05

    # Closing a source string has a smaller positive response.
    closing_quote = bool(re.match(r'''^[\\]*['"][);\s]*$''', token))
    module_line = (bool(re.search(r'\b(?:import|require|from)\b', line))
                   if closing_quote or '\n' in token else False)
    if closing_quote and (module_line or go):
        return new, 2.22 if go else 0.83
    if go and not line.strip() and token.isspace() and '\t' in token:
        return new, 0.57
    if 'include' in line and re.search(r'#\s*include\s*[<"][^>"\n]*$', line):
        if token.startswith('>'):
            return new, 0.21
        if re.search(r'#\s*include\s*<\s*$', tail):
            return new, 0.43
    if direct and token[:1].isspace() and word.isidentifier():
        if word in sys.stdlib_module_names:
            return new, 1.06
    if token.startswith('::') and re.search(
            r'^\s*(?:\d+\s+)?use\b', line):
        return new, 0.92
    if '\n' in token and module_line:
        return new, 0.06
    if s == ' PASS':
        return new, 0.52
    return new, 0.0


def step(carry, prefix, upstream):
    return activation(carry, prefix.token_strings[-1],
                      prefix.document_ids[-1])

"""Sparse lexical and writing-system preferences, not one unified meaning.

The main captured Chinese group is coating/wiping and removal/rectification.
Dictionary cues also cover repetition, increase, charms, attachment and failure.
Chinese 文件 is positive, especially in normative documents, but not near code;
English file labels are negative. Complete split UTF-8 characters before testing.
Korean phonetic classes give negative open-syllable and positive sonorant-coda
offsets. Initial English function words and chat headers have offsets. A document
prefix consisting only of middle dots, and an initial '12', are negative too.
Other tokens are near zero. Many individual lexical preferences remain unmodeled.
"""
from functools import lru_cache
import cedict

READS = ()
ONSETS = 'ㄱㄲㄴㄷㄸㄹㅁㅂㅃㅅㅆㅇㅈㅉㅊㅋㅌㅍㅎ'
VOWELS = 'ㅏㅐㅑㅒㅓㅔㅕㅖㅗㅘㅙㅚㅛㅜㅝㅞㅟㅠㅡㅢㅣ'

# Closed grammatical classes, with offsets for a document's first token.
# Each row gives (members, no leading space, leading space).
INITIAL_WORDS = (
    # Personal pronouns and possessives.
    (frozenset('i me my mine we us our ours you your yours he him his '
               'she her hers it its they them their theirs'.split()), -0.47, -0.21),
    # Prepositions.
    (frozenset('of to in for on with by at from as into about after before '
               'under over between through without within against among during '
               'upon across around'.split()), -0.07, -0.30),
    # Articles, demonstratives, conjunctions, negators.
    (frozenset(('a', 'an', 'the')), 0.06, 0.16),
    (frozenset(('this', 'that', 'these', 'those')), -0.38, -0.38),
    (frozenset('and or but nor so yet if because although while whether'.split()),
     -0.07, -0.16),
    (frozenset(('not', 'no', 'never', 'none', 'neither')), -0.55, -0.55),
)

@lru_cache(maxsize=32768)
def lexical(word):
    senses = tuple(g.lower() for g in cedict.glosses(word))
    gloss = ' | '.join(senses)
    if ('to smear' in senses and
            ('to daub' in senses or 'to plaster' in senses)):
        return -3.6
    if any(g.split(';')[0] == 'to wipe' for g in senses):
        return -2.2
    if 'to brush off' in gloss:
        return -0.55
    if 'to apply (powder' in gloss:
        return -0.65
    if 'to paste' in senses and 'to post (e.g. on a blog)' in senses:
        return -0.95
    if 'to rectify and improve' in gloss:
        return -4.1
    if 'to demolish' in senses and 'to remove' in senses:
        return -1.6
    if word.endswith('除') and len(word) > 1 and (
            'to eliminate' in gloss or 'to get rid of' in gloss):
        return -0.7
    if '(computing) to undo' in gloss:
        return -1.4
    if 'time and again' in gloss:
        return -2.2
    if 'to fill' in senses and 'completely' in senses and 'more' in senses:
        return -2.5
    if 'to heal' in gloss and 'the more' in gloss:
        return -1.7
    if 'talisman' in gloss and 'symbol' in gloss:
        return -2.3
    if 'to add; to attach' in gloss:
        return 0.6
    if 'to be defeated' in gloss and 'failure' in gloss:
        return 1.1
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, b'', '', 0, True)
    _, tail, previous, position, dots_only = carry
    raw = prefix.token_bytes[-1]
    text = raw.decode('utf-8', 'replace')
    split = bool(raw and 0x80 <= raw[0] < 0xc0)
    if split:
        text = (tail + raw).decode('utf-8', 'replace')[-1:]
    word = text.strip()
    value = lexical(word)
    if split and value == -3.6:
        value = -7.0
    if word == '文件':
        # A computer file is different from an official/paper document.
        computer = (
            any(s in previous for s in (
                '目录', '配置', '脚本', '函数', '代码', '读取', '音频',
                '服务器', 'MP3', 'MATLAB', 'hosts', 'index.js',
            )) or any(c in previous[-25:] for c in '`._/')
        )
        value = 0.1 if computer else 1.7
        if '规范性' in previous[-20:]:
            value = 3.8
    if len(word) == 1 and split and '\uac00' <= word <= '\ud7a3':
        syllable = ord(word) - 0xac00
        onset = ONSETS[syllable // 588]
        vowel = VOWELS[(syllable // 28) % 21]
        if syllable % 28 == 0:  # no final consonant
            value = -0.15
            if onset in 'ㄲㄸㅃㅆㅉ' and vowel in 'ㅏㅐㅓㅔ':
                value = -2.0
            if onset in 'ㅋㅌㅎ' and vowel == 'ㅓ':
                value = -3.2
            if onset == 'ㅍ' and vowel in 'ㅓㅐ':
                value = -0.9
            if onset == 'ㅎ' and vowel == 'ㅔ':
                value = -2.5
        # Low front vowels plus a sonorant coda; rounded mid vowels
        # plus /n/ after a fricative or aspirated onset.
        final = syllable % 28
        if vowel == 'ㅐ' and final in (4, 8, 16):  # n, l, m
            value = 1.3
        if vowel == 'ㅗ' and final == 4 and onset in 'ㅅㅆㅊㅋㅌㅍㅎ':
            value = 1.3
    dots_only = dots_only and bool(text) and set(text) == {'·'}
    if word and set(word) == {'·'} and len(word) > 1:
        value = -2.55 if dots_only else -0.1
    if word.lower() in ('file', 'files'):
        value = -0.23 if word.lower() == 'file' else -0.12
    if position == 0:
        if word == '<|im_start|>':
            value = -0.57
        elif value == 0:
            value = -0.07
            for members, bare, spaced in INITIAL_WORDS:
                if word.lower() in members:
                    value = spaced if text.startswith(' ') else bare
                    break
    if position == 1 and previous == '1' and word == '2':
        value = -3.16
    return (doc, (tail + raw)[-6:], (previous + text)[-100:],
            position + 1, dots_only), float(value)

"""A spelling-based approximation: pon/pun is negative, 'go on' positive.

Recognize short p + o/u + n letter fragments, including cases divided
between adjacent tokens. Point- spellings respond more weakly.
Romanization extends these rules to non-ASCII spellings. A negative
fragment can also affect one short, attached word ending. Conversely,
on/onto after a form of go is strongly positive; y/j + nasal fragments
have a smaller positive response. Other tokens default to zero.
"""
import re
from anyascii import anyascii

READS = ()


def spelling(token):
    text = token.strip()
    return (text if text.isascii() else anyascii(text)).lower()


def nasal_tail(text):
    return -5.1 if text.endswith(('nk', 'nkt')) else -1.9


def response(token, previous):
    """Return (response, response on a short following ending)."""
    s, p = spelling(token), spelling(previous)
    attached = bool(token and not token[0].isspace())
    non_ascii = not token.isascii()
    if s in ('on', 'onto') and p in ('go', 'goes', 'going', 'went', 'gone'):
        return (7.7 if p == 'went' else 6.4), 0.
    if s == 'on' and p == 'up':
        return -2.3, 0.
    if attached and re.fullmatch(r'(?:on|un|oun|oon)\w{0,2}', s):
        if p.endswith('ph'):
            return -1.6, 0.
        if p.endswith('p'):
            if s.startswith(('oun', 'oon')):
                return -1.8, 0.
            if s in ('on', 'un'):
                return -5.6, -1.9
            if s in ('ont', 'unt', 'unk', 'unct', 'unkt'):
                return -6.7, nasal_tail(s)
            return -3., 0.
        if p.endswith(('y', 'j')):
            return .9, 0.
    if re.fullmatch(r'p[ou]n', s):
        if non_ascii:
            return -3.7, -1.2
        return (-4.6 if attached else -5.6), -1.9
    if re.fullmatch(r'ponds?', s):
        return (-.9 if attached else -4.3), 0.
    if re.fullmatch(r'p[ou]n[dtks]', s):
        if non_ascii:
            return -2., 0.
        if s == 'pons':
            return -.6, 0.
        if s == 'punt' and previous.strip()[-1:].isdigit():
            return -1.6, -2.3
        return -5.4, nasal_tail(s)
    if re.fullmatch(r'p[ou]n(?:ct|kt)', s):
        return -3.8, (-5.1 if s.endswith('nkt') else -2.3)
    if re.fullmatch(r'p[ou]nt[oa]', s):
        return -2.7, 0.
    if s.startswith(('point', '-point')):
        if s.startswith('pointer'):
            return -.2, 0.
        if non_ascii:
            return -.5, 0.
        if s.startswith('-point'):
            return -2.5, 0.
        return (-1.3 if attached else -.85), 0.
    if s == 'upon':
        return (-3.1 if attached and p[-1:].isalpha() else -.2), 0.
    if s.endswith('pon'):
        return -1.3, 0.
    if re.fullmatch(r'p[ou]n[a-z]{1,3}', s):
        return -.6, 0.
    if token.isascii() and re.fullmatch(r'y(?:on|un)', s):
        return 1.3, 0.
    if s == 'on' and p in (
        'come', 'comes', 'coming', 'came', 'move', 'moves', 'moving'
    ):
        return .8, 0.
    return None, 0.


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous, tail, old_doc = carry if carry else ('', 0., None)
    if old_doc != doc:
        previous, tail = '', 0.
    token = prefix.token_strings[-1]
    value, next_tail = response(token, previous)
    if value is None:
        s = spelling(token)
        attached_ending = (
            not token[:1].isspace() and s.isalpha() and len(s) <= 3
        )
        value = tail if attached_ending else 0.
    return (token, next_tail, doc), float(value)

programs.haiku:
"""layers.1.mlp.down_proj:1037 -- a lexical component.

What it does, in plain terms:
  * Strongly POSITIVE on the particle "on" right after a form of "go"
    ("went on", "going on", "goes on", "go on"): the word "on" in "what is going on".
  * Strongly NEGATIVE on word pieces spelled p-u-n / p-o-n (pun, pon, pond, punk, punct,
    pont, punt, unct, unkt), i.e. the start of words like "Pun..." "Pond" "Punk" "Pont..."
  * Mildly NEGATIVE on "point"/"points" and on a few fragments ending in -unk, -ont, -ong,
    -oon, -oni, -unt; "upon" with no leading space is negative, " upon" barely.
  * Zero everywhere else (about 99% of tokens).
Values are the mean activation of each family on the training rows.
"""

READS = ()

GO_VERBS = {"went", "go", "goes", "going", "gone"}
PUN_PIECES = {"pon", "pun", "pond", "ponds", "pong", "pont", "punk", "punkt", "punct", "punt",
              "punto", "unct", "unkt", "apon", "пон", "пунк"}
WEAK_PIECES = {"unk", "unt", "unta", "ont", "oon", "ong", "oni", "unc"}
POINT_WORDS = {"point", "points", "oints", "-point"}


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1]
    cur = raw.strip().lower()
    prev = prefix.token_strings[-2].strip().lower() if len(prefix.token_strings) > 1 else ""
    if raw == " on" and prev in GO_VERBS:
        return None, 7.0
    if raw == "upon":
        return None, -2.7
    if cur in PUN_PIECES:
        return None, -4.2
    if cur in WEAK_PIECES:
        return None, -0.5
    if cur in POINT_WORDS:
        return None, -0.9
    return None, 0.0

