"""A lexical first-person-singular signal: I, me, my, and translations.

English syntax and the language of nearby words disambiguate short pronouns.
The signal extends to some following auxiliaries, and to selected first-person
verb forms in languages that omit subject pronouns. Selected split foreign
pronouns are joined.
There is a weaker second-person response, a negative response to repeated middle
dots, and a different baseline at the beginning of a document.
"""
import re
from functools import lru_cache
from wordfreq import zipf_frequency

READS = ()
LANGUAGES = ('en', 'fr', 'de', 'it', 'es', 'pt', 'nl', 'sv', 'nb',
             'sh', 'cs', 'pl', 'ro', 'ru')
SUBORDINATORS = set(('if when while because that what why how where whether as '
                    'since although unless before after whenever').split())
PREPOSITIONS = set(('of in on at for to from with by about into upon before '
                    'after without').split())
AUX = {
    'will': 1.6, 'would': 0.4, 'shall': 1.0, 'should': 0.7,
    'can': 1.0, 'could': 0.6, 'may': 0.8, 'might': 0.7,
    'am': 0.7, 'was': 0.5, 'have': 1.1, 'had': 0.4,
    'do': 0.45, 'did': 0.25, 'don': -0.3, 'didn': 0.1,
    "'ll": 1.5, "'ve": 0.55, "'m": 0.3, "'d": 0.35,
    'cannot': 1.0, 'must': 0.4,
}
MENTAL_VERBS = set(('think know see like hope wish believe feel understand '
                    'find love remember').split())
ADVERBS = set(('not just really also still already only actually personally '
               'definitely certainly never').split())
GERMAN = set('ich mich mir mein meine meiner meinem meinen meines'.split())
RUSSIAN = set(('я меня мне мой моя мое моё мои '
               'моей моих моим мою мо').split())
ROMANCE = set(('eu mim meu minha meus minhas yo mí mío mía míos mías '
               'io mio mia miei mie moi mi mis').split())
NORTHERN = set('ik mij mijn jag mig minä minun jeg'.split())
FRENCH = {'je': 4.5, 'j': 2.4, 'm': 2.1, 'mon': 3.8, 'ma': 3.0, 'mes': 3.1}
SPEAKER_VERBS = {
    'it': set('ho posso penso voglio faccio so devo spero credo vedo'.split()),
    'pt': set('sou estou posso penso quero tenho faço sei devo espero vejo vou vim'.split()),
    'es': set('soy estoy puedo pienso quiero tengo hago sé debo espero creo veo'.split()),
    'ru': set('могу знаю хочу думаю считаю понимаю вижу'.split()),
}

@lru_cache(maxsize=50000)
def frequency(word, lang):
    return min(6.0, zipf_frequency(word, lang))


def language(text):
    text = re.sub(r'<[^>]*>', ' ', text)
    words = [w for w in re.findall(r'[^\W\d_]+', text.lower())
             if len(w) > 1 and w not in {'user', 'assistant', 'system'}][-7:]
    scores = {lang: sum(frequency(w, lang) for w in words) for lang in LANGUAGES}
    best = max(scores, key=scores.get)
    return best if scores[best] > scores['en'] + 0.4 * len(words) else 'en'


def step(carry, prefix, upstream):
    doc, token = prefix.document_ids[-1], prefix.token_strings[-1]
    first = carry is None or carry[0] != doc
    _, previous, recent, speaker = (doc, '', '', 0.0) if first else carry
    word, prev = token.strip(), previous.strip().lower()
    boundary = token[:1].isspace() or not previous or not previous[-1:].isalnum()
    # A pronoun may span more than one token, e.g. Me + ine or мо + ю.
    match = re.search(r'[^\W\d_]+$', recent + token)
    whole = match[0] if match else word
    lower = word.lower()
    joined = not boundary and whole.lower() in GERMAN | RUSSIAN | ROMANCE | NORTHERN
    if joined:
        word, lower, boundary = whole, whole.lower(), True
    # Positive state carries an English subject into its verb; negative
    # state marks a just-seen object pronoun or possessive.
    value, next_speaker = -0.005, 0.0

    if boundary and word in ('I', 'i'):
        value = 1.35 if word == 'I' else 0.15
        if prev in SUBORDINATORS:
            value = 2.1 if word == 'I' else 0.7
        elif prev in {'and', 'but', 'or'}:
            value = 1.7 if word == 'I' else 0.45
        elif prev in AUX:
            value = 2.3
        elif prev in {'maybe', 'perhaps'}:
            value = 2.3
        elif prev in PREPOSITIONS or prev in {'the', 'a', 'an', 'type'}:
            value = 0.0
        elif not token[:1].isspace():
            value = 0.95 if word == 'I' else 0.1
            if any(c in previous for c in '({}=$'):
                value = 0.1
        elif prev == ':':
            value = 0.7
        if value > 0.5 and language(recent) != 'en':
            value *= 0.35
        next_speaker = 1.0 if value > 0.4 or word == 'I' else 0.0
    elif boundary and lower in {'me', 'my', 'mine', 'myself'}:
        value = {'me': 2.6, 'my': 1.7, 'mine': 1.8, 'myself': 1.4}[lower]
        if lower == 'me':
            if not token[:1].isspace() or word != 'me':
                value = 1.0
            if prev in {'let', 'for'}:
                value = 2.9
            elif prev in {'the', 'a', 'an'}:
                value = 0.4
            elif prev in {'in', 'of', 'from', 'and'}:
                value = 1.8
            next_speaker = -1.0
        elif lower == 'my':
            if word != 'my' or not token[:1].isspace():
                value = 1.2 if word == 'My' else 0.4
            if prev in PREPOSITIONS or prev in {'is', 'was', 'that'}:
                value = 2.0
            if word == 'My' and any(c in previous for c in '.!'):
                value = 2.1
            if prev in {'class', 'new', 'const', 'type', '=', '{'}:
                value = 0.0
            next_speaker = -1.0
    elif boundary and lower in {'you', 'your', 'yours', 'yourself', 'we', 'us', 'our'}:
        value = {'you': 0.58, 'your': 0.18, 'yours': 0.2, 'yourself': 0.3,
                 'we': 0.06, 'us': -0.05, 'our': -0.18}[lower]
    elif boundary and lower in GERMAN:
        value = 4.1 if lower == 'ich' else (2.0 if lower == 'mir' else 2.6)
        if lower == 'ich' and language(recent) not in {'de', 'en'}:
            value = 0.1
        if prev == '@':
            value = 0.0
    elif boundary and lower in RUSSIAN:
        value = 3.6 if lower == 'я' else (3.3 if lower == 'мо' else 2.2)
    elif boundary and lower in FRENCH and language(recent) == 'fr':
        value = FRENCH[lower] if not word.isupper() or word == 'J' else 0.1
    elif boundary and lower in ROMANCE | NORTHERN:
        if not word.isupper() and language(recent) in {'fr', 'it', 'pt', 'es', 'nl', 'sv', 'nb'}:
            value = 2.6
    elif '我' in word and not any(p in word for p in ('我们', '我們', '我国', '我國')):
        value = 2.2
    elif word in {'私', '僕', '俺', 'わたし', '私は', '私の'}:
        value = 0.8 if word == '私' else 1.7
    elif word in {'저', '제', '나', '내', '你', '您'}:
        value = 0.6
    elif word == 'ني':
        value = 1.8
    elif lower == 'user' and previous.endswith('>'):
        value = 0.65
    elif speaker > 0:
        form = lower.replace('’', "'")
        if form in AUX:
            value, next_speaker = speaker * AUX[form], speaker * 0.65
        elif lower in {'want', 'need'}:
            value = speaker * 1.3
        elif lower in MENTAL_VERBS:
            value = speaker * 0.6
        elif lower in ADVERBS or form == "'t":
            value, next_speaker = speaker * 0.5, speaker * 0.9
        elif token.startswith(' ') and word.isalpha():
            value = speaker * 0.3
    elif speaker < 0 and token.startswith(' ') and word.isalpha():
        value = 0.65 if lower in {'own', 'self'} else 0.25

    if word in {"'", '’', "'ai", '’ai'} and prev in {'j', 'm'} and language(recent) == 'fr':
        value = 2.6
    if token[-1:].isalpha():
        verb = whole.lower()
        context = (recent + token)[:-len(whole)]
        possible = [lang for lang, forms in SPEAKER_VERBS.items() if verb in forms]
        if possible and language(context) in possible:
            value = 4.5 if language(context) == 'it' else 2.8
        elif not boundary and len(verb) >= 5 and verb.endswith(('ei', 'i')):
            if language(context) == 'pt' and frequency(verb, 'pt') > 2.0:
                value = 3.0  # Portuguese first-person past-tense endings.
    if word and set(word) <= {'·'} and len(word) > 1:
        value = -1.85
    if first:
        value, next_speaker = -0.15, 0.0
        if lower in {'i', 'my'}:
            value = -0.6 if token.startswith(' ') else -2.3
            if lower == 'my':
                value = -0.8 if token.startswith(' ') else -3.0
        elif lower == 'me':
            value = 1.3
    return (doc, token, (recent + token)[-160:], next_speaker), float(value)

"""A code-syntax signal, rather than a general prose feature.

Shell option prefixes are negative, especially immediately after an executable;
paths and shell operators have smaller negative values. Qualified names in
package/namespace declarations are positive, while the following import or
opening namespace brace is negative. Everything else is approximately silent.
Additional small rules cover document-opening headings/declarations, Java
package directories, and middle-dot-only text suffixes.
Only a short text suffix and declaration/import state are retained.
"""
import re

READS = ()

# Executables and their familiar subcommands: this is a shell vocabulary,
# not a list of token IDs.
COMMANDS = set('''cat grep egrep fgrep rg head tail sed awk find xargs ls cd
pwd mkdir rm rmdir cp mv chmod chown curl wget ssh scp tar unzip zip echo
printf test declare export source git diff log status show checkout reset
python python3 pip pip3 pytest node npm npx yarn pnpm tsc ts-node cargo
rustc go java javac mvn gradle gradlew docker kubectl bash sh zsh make cmake
sudo timeout env sort uniq cut wc tee jq apt apt-get brew ssh-keygen
ssh-keyscan openssl install configure helm shopt du df ps kill root gcloud
php ruby perl'''.split())
COMMAND_RE = re.compile(r'(?<![\w.])(' + '|'.join(
    re.escape(x) for x in sorted(COMMANDS, key=len, reverse=True)
) + r')(?![\w.])')
DECLARATION = re.compile(
    r'(?:^|[\n;])[ \t]*[+-]?(?:\d+[ \t]+)?'
    r'(package|namespace)\b[ \t]*([\w.\\]*)[\r\n\t ]*$'
)


AMBIGUOUS = {'find', 'test', 'source', 'make', 'export', 'show', 'log',
             'diff', 'status', 'sort', 'uniq', 'cut', 'tee', 'go', 'echo',
             'head', 'tail', 'install', 'root', 'du', 'df', 'ps'}

def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        before, package, imports, position = '', False, 0, 0
    else:
        _, before, package, imports, position = carry
    token = prefix.token_strings[-1]
    s = token.strip()
    # Escaped newlines in quoted source are useful context too.
    context = before.replace('\\n', '\n')
    context = re.sub(r'\\+\n[ \t]*', ' ', context)
    line = context.rsplit('\n', 1)[-1]
    line = re.sub(r"`[^`]*`", "", line)
    commands = [m for m in COMMAND_RE.finditer(line[-180:])
                if m.group() not in AMBIGUOUS or
                re.search(r"(?:^|[;|&`\"'$])\s*$", line[-180:][:m.start()])]
    command = bool(commands)
    last_word = re.search(r'([\w-]+)$', before)
    last = last_word.group(1) if last_word else ''
    immediate = last in COMMANDS and (last not in AMBIGUOUS or command)
    value = 0.0

    if s in ('-', '--') and token.startswith(' '):
        if immediate:
            value = -3.5 if last in {'grep', 'head', 'tail'} else -2.9
        elif re.search(r'\bif\s+\[+\s*!?$', line):
            value = -2.0
        elif before.endswith('--'):
            value = -0.6
        elif re.search(r'\btest [^\n]*\.rs$', line):
            value = -0.6
        elif command:
            value = -2.1
        elif s == '--':
            value = -1.7 if before.endswith('linux') else 0.0
        elif re.search(r'\.[a-z]{1,4}$', before):
            value = -0.6
    elif s in ('--', '-') and before.endswith(('`', '"', "'")):
        value = -1.0 if s == '--' else -0.5
    elif token in (' /', ' ./'):
        value = -1.2 if command or before.endswith(' >') else -0.08
    elif token == ' &&':
        value = -0.45 if command else -0.07
        if re.search(r'\bcd\s', line):
            value = -0.85
    elif token == ' |':
        value = -0.8 if command or '>&' in line else 0.0

    declaration = DECLARATION.search(before.replace('\\n', '\n'))
    if declaration and s not in ('\\n', '\\r', ''):
        kind, name = declaration.groups()
        if s.startswith('{'):
            value = -5.0 if 'using ' in before or '.' in name else -3.5
        elif s in ('.', '\\') or (
            len(s) > 1 and s[0] in '.\\' and s[1].isalpha()
        ):
            if s.startswith('\\'):
                value = 3.5 if name.count('\\') == 0 else 6.0
            else:
                value = 1.3 + min(2.5, 0.65 * name.count('.'))
        elif name.endswith('.') and s.isidentifier() and not token[:1].isspace():
            value = 2.0
        elif not name and s.isidentifier() and token[:1].isspace():
            if kind == 'package':
                if s == 'org':
                    value = 7.3
                elif s == 'com':
                    value = 4.5
                else:
                    value = 1.8 if len(s) == 2 else 0.5
                if s == 'main':
                    value = 0.0
            else:
                value = 0.3

    if s.startswith('.') and len(s) > 1 and s[1].isupper():
        if re.search(r'(?:^|\n)using [\w.]*$', before):
            value = 1.4

    if s == 'package' and re.fullmatch(r'[ \t]*[+-]?(?:\d+[ \t]+)?', line):
        package, imports = True, 0
    if token == 'import':
        if package:
            value = -3.5 if imports == 0 else -0.7
            if before.endswith('\\n'):
                value *= 0.15
            imports += 1
        elif re.search(r'(?:import|package) [\w.]+;\s*$', before):
            value = -0.65
    if token == 'use' and re.search(r'namespace [^;]+;\s*$', before):
        value = -2.5
    if token.startswith('/**') and package and imports == 0:
        value = -1.3
    if s in ('[', '[[') and re.search(r'\bif$', before):
        value = -1.4
    if token == 'public' and package and imports == 0:
        value = -1.4
    if s in ('class', 'func', 'interface'):
        package = False

    # Reverse-domain directories used for Java sources and Maven artifacts.
    if s.startswith('/') and s[1:] in {'org', 'com', 'net', 'io', 'edu', 'gov'}:
        value = 1.4 if s == '/org' else 0.35
    elif len(s) > 2 and s.startswith('/') and before.endswith('/org'):
        value = 1.7
    if position == 0:
        if s in ('#', '##'):
            value = -0.9
        elif s == 'using':
            value = -1.1
        elif s == 'def':
            value = -2.2
    if s and set(s) == {'·'} and len(s) > 1 and not before.strip('·'):
        value = -1.1
    return (doc, (before + token)[-256:], package, imports, position + 1), value

"""A spelling-sensitive until/till/til feature, including split word fragments.

Nearby Scandinavian function words weaken till; waiting verbs strengthen
until/till. TeX commands (\\tilde) are excluded. Related util/unto, Dutch
prepositions, and Persian ta have smaller or separate responses. A few
contrasting t-initial spellings are negative. Unlisted tokens are near zero;
the first token of each document gets a negative offset. This is a spelling
approximation, not a detector for every expression of time or direction.
"""
import re

READS = ()
NORDIC = {'och', 'att', 'jag', 'är', 'för', 'inte', 'ett', 'ska',
          'utan', 'har', 'med', 'og', 'jeg', 'uten', 'kan',
          'om', 'av', 'det', 'en', 'som', 'på'}
TIL_ENDINGS = {'il', 'ill', 'ills', 'illa', 'illas', 'illing', 'ild', 'ilden'}


def step(carry, prefix, upstream):
    start = (prefix.position == 0 or
             prefix.document_ids[-1] != prefix.document_ids[-2])
    history = '' if start else carry
    token = prefix.token_strings[-1]
    previous = '' if start else prefix.token_strings[-2]
    word = token.strip()
    lower = word.lower()
    glued = bool(token) and not token[0].isspace()
    value = -0.003

    if lower == 'until':
        value = 3.65 if word.islower() else (3.8 if glued else 3.2)
        if previous.strip().lower() in {'wait', 'waiting', 'waited'}:
            value += 2.5
    elif lower in {'til', 'till'}:
        if glued and previous.endswith('\\'):
            value = -0.1  # TeX's \tilde, not a word containing til.
        elif lower == 'til':
            value = 4.8 if glued else 3.45
        elif word[0].isupper():
            value = 7.8
        else:
            nordic = NORDIC.intersection(re.findall(r'\w+', history.lower()))
            value = 2.8 if nordic else 5.3
        if previous.strip().lower() in {'wait', 'waiting', 'waited'}:
            value += 3.0
    elif lower == 'unto' and not glued:
        value = 2.6
    elif lower == 'util':
        value = 0.9 if word[0].isupper() else 1.2
        if glued and previous[-1:].isalpha():
            value += 0.65
            if previous.endswith(('t', 'T')):
                value += 1.2
    elif glued and previous.endswith(('t', 'T')):
        if lower in TIL_ENDINGS:
            value = 2.6
            if lower in {'il', 'ill'} and previous.strip() == 'T':
                value = 9.0
        elif lower in {'ell', 'ello', 'ella', 'yll'}:
            value = 1.0
        elif lower in {'l', 'll', "'ll", '’ll'}:
            value = 0.65
        elif lower == 'iling':
            value = 0.6
    # Contrasting t-initial spellings: tay, tank, town, toll, tur.
    fragment = None
    if glued and previous.endswith(('t', 'T')):
        fragment = lower
    elif lower in {'tay', 'tow', 'toll'}:
        fragment = lower[1:]
    if fragment in {'ay', 'ank', 'own', 'ow', 'oll', 'ur'}:
        value = -4.0 if fragment == 'ay' else (
            -2.6 if fragment == 'ank' else -1.5)
    if token == 'ا' and previous.endswith('ت'):
        value = 6.3  # Persian ta: 'to/until'.
    if lower == 'toe' and not glued:
        value = 2.0
    if lower == 'tot' and not previous.endswith('\\'):
        value = 1.2  # Dutch to/until (also appears as fragments).
    if lower == 'o' and glued and previous.lower().endswith('nt'):
        value = 2.0  # 'into' or 'to' after an escaped newline.
    if start:
        value -= 0.3
    return (history + token)[-160:], value

"""Approximate a document-onset pulse using readable token classes.

Large training activations concentrate at the first token of a document,
and can persist while that token repeats. Predict zero after the first
change of token. At onset, use decimal identity, whitespace, capitalization,
English word frequency, function words, and punctuation to set the strength.
These classes deliberately omit the component's finer lexical exceptions.
"""
from functools import lru_cache
from wordfreq import zipf_frequency
import unicodedata

READS = ()
# Decimal digits have different strengths, with zero particularly strong.
DIGITS = (-11.15, -4.84, -4.77, -1.03, -2.52,
          -2.24, -2.54, -2.19, -3.42, -5.91)
FUNCTION_WORDS = frozenset('''a an the and or but if as than then that this
these those of to in on at by for from with into through without over under
between he she it they we i you him her them us my your his its our their
is are am was were be been being have has had do does did can could may
might must shall should will would'''.split())


@lru_cache(maxsize=8192)
def onset(token):
    s = token.strip()
    if token.startswith('<|'):
        return 0.6
    if len(token) == 1 and token in '0123456789':
        return DIGITS[int(token)]
    if not s:
        if token == ' ':
            return 0.1
        if set(token) <= {'\n'}:
            return min(1.1, 0.58 * len(token))
        return -3.6 if '\n' not in token else -2.0
    if s.isascii() and s.isalpha():
        if s.lower() in FUNCTION_WORDS:
            return -1.8 if s.islower() and token == s else -0.4
        frequency = zipf_frequency(s.lower(), 'en')
        if s[0].isupper():
            if len(s) == 1:
                return -0.9
            if not s.istitle():
                return -1.8
            if frequency < 4.0:
                return -1.9
            return -1.1 if token.startswith(' ') else -0.4
        return -3.0 if token.startswith(' ') else -2.4
    if '\\' in s:
        return -6.0 if s.replace('\\', '').isalpha() or len(s) == 1 else -10.5
    if any(ch.isalpha() for ch in s):
        return -1.3 if not s.isascii() else -3.6
    if any(unicodedata.category(ch) == 'Sc' for ch in s):
        return -6.4
    if s == ',':
        return -2.6
    if s == '.':
        return -0.4
    if s.startswith('#'):
        return -3.7
    return -2.3


def step(carry, prefix, upstream):
    doc, token = prefix.document_ids[-1], prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        return (doc, token, True), onset(token)
    _, first, repeating = carry
    repeating = repeating and token == first
    value = onset(token) if repeating else 0.0
    return (doc, first, repeating), value

programs.haiku:
"""Document-start detector, by what the first token of a document is.

Inside a document this component is almost silent (its activation there is about
+-0.05). On the first token of each document (the token right after a document break,
or the first token of a row, where the model has no earlier context) it writes a
clearly negative activation, whose size depends on what that token looks like:

- common function words and pronouns ("the", " a", " of", "This", "It"): about -0.5;
- capitalised words (titles, sentence openers, class names): a little negative, -0.5;
- lowercase content words and fragments ("file", " variable", " path"): clearly
  negative, -2.8;
- non-ASCII text: -1.2;
- digits: -4.5 (the most negative, "0" goes to about -11 in the model);
- punctuation, code symbols, and runs of one repeated character: -3.5.

It predicts those values at each document start and 0 at every other position.
What it misses: the spread of values within each class, the small mid-document values
(about 40% of the component's effect on the output), and the cases where a second digit
repeats the first.
"""

import re

READS = ()

FUNCTION_WORDS = set(
    """a an the of and or to in on at by for from with as is are was were be been it its
    this that these those i you he she we they me my your his her our their not no but if
    so than then there here do does did have has had will would can could should may
    might must one also all any some just about into over up out""".split()
)

CAPITALISED_VALUE = -0.5
FUNCTION_VALUE = -0.5
CONTENT_VALUE = -2.8
SYMBOL_VALUE = -3.5
DIGIT_VALUE = -4.5
NONASCII_VALUE = -1.2


def _value(token):
    word = token.strip()
    if not token.isascii():
        return NONASCII_VALUE
    if word.isdigit():
        return DIGIT_VALUE
    if len(word) > 1 and len(set(word)) == 1:
        return SYMBOL_VALUE  # a run of one repeated character
    if re.fullmatch(r"[^\w\s]+", word):
        return SYMBOL_VALUE  # punctuation or code symbols
    if re.fullmatch(r"[A-Za-z]+", word) is None:
        return CONTENT_VALUE  # mixed identifiers and fragments
    if word.lower() in FUNCTION_WORDS:
        return FUNCTION_VALUE
    if word[0].isupper():
        return CAPITALISED_VALUE
    return CONTENT_VALUE


def step(carry, prefix, upstream):
    t = prefix.position
    starts_doc = t == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]
    if not starts_doc:
        return None, 0.0
    return None, _value(prefix.token_strings[-1])

"""Layer 1, MLP down-projection, component 1050: a "talking about words" detector.

The component fires in text about wording, meaning or languages. It responds to:
- the words themselves: "word", "words", "plural", "verb", "phrase", "translation",
  "meaning", "grammar" (strongest);
- the names of languages: "English", "German", "Latin", ... (medium);
- weaker: "means", "language", "name", and opening quote marks;
- the gloss position: a colon, "for", "as" or a quote mark right after a language or
  word-term, as in "(Russian: ...", "the Tamil word for ...", "English \"...".
Each token gets a fixed weight from its class; everything else is 0. The weights are the
class mean activations measured on training rows, scaled by 0.75 (the least-squares
scale). It explains only about 5% of the variance: the component's large spikes depend
on context this list cannot see.
"""

READS = ()

TERMS = {
    "word", "words", "term", "terms", "plural", "singular", "verb", "tense",
    "adjective", "spelling", "phrase", "translation", "translated", "translate",
    "dialect", "grammar", "vocabulary", "sentence", "meaning", "meanings", "sense",
}
LANGUAGES = {
    "english", "spanish", "german", "japanese", "hebrew", "arabic", "greek", "latin",
    "dutch", "swedish", "french", "russian", "korean", "hindi", "tamil", "welsh", "chinese",
}
MEANS = {"means", "mean", "meant", "language", "languages"}
NAMES = {"name", "names"}
QUOTES = {'"', "“", "„"}
GLOSS_MARKS = {":", "for", "as", '"', "“"}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1].strip().lower()
    previous = prefix.token_strings[-2].strip().lower() if len(prefix.token_strings) > 1 else ""
    if token in GLOSS_MARKS and (previous in TERMS or previous in LANGUAGES):
        value = 0.75
    elif token in TERMS:
        value = 1.1
    elif token in LANGUAGES:
        value = 0.6
    elif token in MEANS:
        value = 0.4
    elif token in NAMES:
        value = 0.15
    elif token in QUOTES:
        value = 0.1
    else:
        value = 0.0
    return None, value

programs.sol:
"""Sparse surface-pattern approximation, chiefly for web-page furniture.

The strongest negative rules recognize textbook exercise references (notably
"In Exercises" and chapter/problem selectors). Other rules cover educational
audience/difficulty labels, metadata colons, view counts, and page previews.
URL separators, dot leaders, and a code namespace have separate responses.
Most ordinary text is near zero; document beginnings get a small word-shape
baseline, refined for subject pronouns, code declarations/imports, and escaped
tabs. This is a partial surface-pattern explanation, not a subject classifier.
"""
import re

READS = ()


def predict(token, before, position, dot_document=False):
    word = token.strip()
    if len(word) >= 2 and set(word) == {'·'}:
        return 0.80 if dot_document else 0.08
    if token == '://':
        return 0.40 if before.endswith('http') else 0.26

    # Labels and controls on educational sites and discussion forums.
    if word == 'Level' and before.endswith(' Challenge'):
        return -1.50
    if word == 'Challenge' and re.search(r'(Stage|Age):?[^\n]{0,20}\Z', before):
        return 0.37
    if word in {'Students', 'Teachers'} and before.endswith('\nFor'):
        return -1.10 if word == 'Students' else -0.85
    if word == 'Views' and before.endswith('\n') and 'Replies' in before:
        return 0.85
    if word == 'preview' and before.endswith('This'):
        return 1.10
    if word in {'page', 'pages'} and before.endswith(' preview shows'):
        return 1.10
    if word == 'Exercises':
        if re.search(r'\bIn\Z', before):
            return -9.0 if before.endswith('Graphical Analysis In') else -7.5
        return -0.40
    if word == 'Exercise':
        return -0.10
    if word == 'Problem':
        if before.endswith('Chapter:'):
            return -6.4
        if before.endswith('Textbook'):
            return -6.3
        if re.search(r'Chapter [\d.]+,\Z', before):
            return -9.0
        if re.search(r'Chapter [\d.]+ -\Z', before):
            return -2.6
        if re.search(r'Chapter [\d.]+\Z', before):
            return -4.3
    if word == 'Worksheet' and before.endswith('Math\n'):
        return 0.60
    if word == 'Ch' and re.search(r'#{3,}\Z', before):
        return -1.40
    if word == 'editions' and before.endswith('View more'):
        return -2.70
    if word == 'Shopping' and before.endswith('Continue'):
        return 0.75
    if word == 'App' and re.search(r'(Open|Watch) in\Z', before):
        return -1.95 if before.endswith('Open in') else -0.95
    if word == 'satisfied' and re.search(r'\d[\d,]*\Z', before):
        return 0.70

    # Colons closing recognizable metadata fields or forum reply prefixes.
    if word == ':':
        if before.endswith('\nRe'):
            return -0.60
        if before == 'Title':
            return -1.35
        if before.endswith('Alternate ISBN'):
            return -3.4
        if re.search(r'\dISBN-13\Z', before):
            return -1.6
        if before.endswith('ISBN'):
            return -0.6
        if re.search(r'Question \d{4,}\Z', before):
            return -1.00
    if token == '.Tasks' and before.endswith('System.Threading'):
        return -2.50

    if position == 0:
        # Sentence subjects versus source-code declarations at document starts.
        if word in {'I', 'You', 'He', 'She', 'It', 'We', 'They'}:
            return 0.20 if token.startswith(' ') else 0.60
        if word in {'import', 'using'}:
            return -0.45
        if word in {'int', 'char', 'void', 'const', 'func', 'function'}:
            return -1.4 if token[0].isalpha() else -0.6
    if position == 0 and token == r'\t':
        return -1.95
    if position == 0 and word.isalpha():
        if word.islower() and (not token.startswith(' ') or len(word) > 3):
            return 0.30
        if word.istitle():
            return 0.25 if len(word) > 3 else 0.12
        if not word.isascii():
            return 0.16
    return -0.001


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    if carry is None or carry[0] != document:
        before, position = '', 0
        first = prefix.token_bytes[-1].decode('utf8', 'replace')
        dot_document = bool(first) and set(first) == {'·'}
    else:
        _, before, position, dot_document = carry
    token = prefix.token_bytes[-1].decode('utf-8', errors='replace')
    value = predict(token, before, position, dot_document)
    return (document, (before + token)[-160:], position + 1, dot_document), value

programs.haiku:
"""Stand-in nouns: negative on general words that name an unspecified thing, person,
place, amount or time, such as "those", "one", "person", "region", "amount", "period",
"matter" or "factor". Their meaning is supplied by a following "of", "that" or "who"
phrase, so the component fires (negatively) on them.

The size depends on context:
- right after "the" or "a" (the word heads a noun phrase), the full value applies;
- after other words the value is near zero;
- demonstrative pronouns ("those", "ceux", "celui") are negative anywhere, and more so
  after "than", "as", "like" or "including";
- indefinite pronouns ("something", "anyone") are mildly negative anywhere;
- "that" and "any" are negative when they follow "than", "as", "to", "from", "with", etc.
  (they are then pronouns, not complementizers or determiners).

Everything else predicts 0. Values are in the component's activation units.
"""

READS = ()

DEMONSTRATIVES = {"those", "ceux", "celui", "celle"}
INDEFINITE = {"something", "anything", "someone", "anyone", "somebody", "anybody"}
# Strong: general nouns for people, places, parts, amounts, times and things.
PEOPLE_AND_PLACES = {"one", "ones", "person", "persons", "place", "places", "region", "regions",
                     "portion", "party", "parties", "area", "areas", "part", "parts", "side",
                     "location", "locations", "territory", "zone", "space", "people", "man"}
AMOUNTS_AND_TIMES = {"amount", "amounts", "number", "numbers", "quantity", "period", "periods",
                     "date", "time", "duration", "age"}
GENERAL_THINGS = {"matter", "matters", "thing", "things", "entity", "phenomenon", "device",
                  "devices", "mechanism", "substance", "item", "items", "element", "elements"}
# Medium: abstract nouns that take a complement ("the factor of", "the case that").
ABSTRACT = {"factor", "factors", "aspect", "aspects", "situation", "situations", "kind", "case",
            "cases", "information", "position", "point", "points", "term", "terms", "measure",
            "measures", "role", "change", "changes", "provision", "provisions", "ability",
            "manner", "feature", "features", "version", "issue", "issues", "fact"}
# Weak: very general nouns (type, method, way, use).
WEAK = {"type", "types", "method", "methods", "range", "use", "way", "form", "set", "process"}

STRONG, MEDIUM, WEAK_VALUE = -1.5, -0.9, -0.4
VALUE = {}
for group, value in [(PEOPLE_AND_PLACES, STRONG), (AMOUNTS_AND_TIMES, STRONG),
                     (GENERAL_THINGS, STRONG), (ABSTRACT, MEDIUM), (WEAK, WEAK_VALUE)]:
    for word in group:
        VALUE[word] = value
VALUE["ones"] = -4.0  # "the ones" is the strongest case

DETERMINERS = {"the", "The", "THE", "a", "A", "an", "An"}
COMPARE = {"than", "as", "like", "including", "such", "especially", "except"}
PRONOUN_AFTER = {"any": {"than", "including", "or", "like", "as"},
                 "that": {"than", "as", "to", "from", "with", "except", "like", "including"}}


def step(carry, prefix, upstream):
    cur = prefix.token_strings[-1].strip().lower()
    prev = prefix.token_strings[-2].strip() if len(prefix.token_strings) > 1 else ""
