    if token.startswith('<|'):
        return 0.09
    if token.isspace():
        if '\n' in token:
            return 0.7 if token.count('\n') >= 2 else -0.04
        if token.strip(' ') == '':
            return -0.54 * len(token) if len(token) <= 2 else (
                -1.21 if len(token) == 3 else -0.09
