OPENING_DIGITS = (0.56, 0.13, 0.33, 0.05, 0.17,
                  0.32, 0.48, 0.38, 0.44, 0.26)
CHAT_BOUNDARIES = {
    '</tool_call>': 0.15, '</tool_response>': -0.08,
    '<think>': -0.10, '</think>': 0.04,
