        value = 0.91
    elif s.startswith('#'):
        value = 0.54
    elif s == '\\n':
        value = 0.91
    elif s == '\t':
        value = 0.74
    elif len(s) == 1 and s in '0123456789':
        value = OPENING_DIGITS[int(s)]
    elif w.lstrip('.').lower() == 'new':
        value = 0.79
    elif w in {'[', ']', '{', '}'}:
        value = -0.30
    elif len(w) == 1 and w.isascii() and w.isalpha():
        value = -0.12
    elif s == '%':
        value = 1.29
