def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_ids[-1]
    s = prefix.token_strings[-1]
    new_doc = carry is None or carry[0] != doc
    if new_doc:
        initial, opening = token, True
        history, singles, quotes, kana = deque(), 0, 0, 0
    else:
        _, initial, opening, history, singles, quotes, kana = carry
        opening = opening and token == initial

    # Recent prose fragmented into individual Han characters has a larger
    # response on Chinese grammatical words. Quotes identify dialogue.
    density = singles / max(1, len(history))
    quoted, japanese = quotes > 0, kana > 0
    flags = (int(bool(HAN.fullmatch(s))),
             int(any(c in s for c in '“”「」『』')),
             int(bool(KANA.search(s))))
    if len(history) == 64:
        a, b, c = history.popleft()
        singles, quotes, kana = singles - a, quotes - b, kana - c
    history.append(flags)
    singles, quotes, kana = (singles + flags[0], quotes + flags[1],
                            kana + flags[2])
