        return state, opening_value(s)

    previous = prefix.token_strings[-2].strip()
    boost = 0.55 * (density - 0.4)
    if s == '那':
        value = 0.35 + boost
    elif s in {'这', '這'}:
        value = 0.18 + boost + 0.08 * quoted
    elif s in SPEECH:
        value = 0.06 + boost + 0.24 * quoted
    elif s == '你':
        value = 0.06 + boost + 0.12 * quoted
    elif s == '被':
        value = 0.10 + boost
    elif s == '了':
        value = -0.03 + 0.18 * (density - 0.4)
        value += 0.12 * bool(HAN.fullmatch(previous))
    elif s == '俺':
        # Chinese colloquial "I", versus the same character in Japanese.
        value = 1.5 if not japanese and density > 0.25 else -0.15
    elif s == '休':
        # Prohibitive 你休... and cessation 罢休, not leisure/holidays.
        value = 1.3 if previous in {'你', '罢', '罷'} else -0.14
    elif s == '要' and previous == '休':
        value = 1.8
    elif '：' in s and any(c in s for c in '“「『'):
        value = 0.20 + boost
    elif s in CHAT_BOUNDARIES:
        value = CHAT_BOUNDARIES[s]
    elif '\xa0' in s:
        value = -0.035
    else:
        value = -0.002
    return state, float(value)

