"""Candidate 4: punctuation runs, dashes, ellipses, document starts."""
READS = ()
RULE_CHARS = set(".-=_")       # ellipses, dash rules, equals and underscore lines
MARK_CHARS = set("*#~!+^")     # bullets, headers, tildes
LEVEL = {"…": 2.0, "—": 1.1, "–": 0.5}   # single dash or ellipsis characters

def step(carry, prefix, upstream):
    if prefix.position == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        return carry, -0.6          # first token of a document
    s = prefix.token_strings[-1]
    core = s.strip()
    if len(core) >= 2 and len(set(core)) == 1:
        if core[0] in RULE_CHARS or core[0] == "…":
            return carry, 1.75      # a repeated rule or ellipsis: ..., ---, ===, ___
        if core[0] in MARK_CHARS:
            return carry, 1.0       # repeated marks: **, ##, ~~
    if core in LEVEL:
        return carry, LEVEL[core]   # a dash or ellipsis used as punctuation
    return carry, 0.0

