"""Negative pulses when a Latin-letter run reaches three letters.

The strongest case is an uppercase abbreviation assembled across tokens.
Two-letter-prefix plus one-letter endings are stronger than the reverse.
Lowercase fragments respond less, except all-consonant runs. English word
frequency provides a small commonness correction. Whole three-letter tokens
have a weaker response; other run lengths predict zero. This describes
orthography and token splitting, not what an abbreviation means.
"""
import re
from functools import lru_cache
from wordfreq import zipf_frequency

READS = ()
VOWELS = frozenset('aeiou')


@lru_cache(maxsize=32768)
def commonness(text):
    return zipf_frequency(text.lower(), 'en')


def amplitude(piece, word, previous_piece, joined):
    if len(word) != 3:
        return 0.0
    if not joined:
        if not piece.isupper():
            return -0.01
        if commonness(piece) < 3.75:
            return -0.47
        return -0.10

    if word.isupper():
        if len(previous_piece) < 2:
            return -1.72 if commonness(word) < 3.25 else -0.87
        return -1.82 if commonness(word) < 1.75 else -2.49

    if not any(c.lower() in VOWELS for c in word):
        return -0.36 if previous_piece.isupper() else -1.04
    previous_has_vowel = any(c.lower() in VOWELS for c in previous_piece)
    return -0.59 if previous_has_vowel else -0.26


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        oldword = previous_piece = ''
    else:
        _, oldword, previous_piece = carry
    token = prefix.token_strings[-1]
    match = re.search(r'[A-Za-z]+', token)
    piece = match.group() if match else ''
    joined = bool(match and match.start() == 0 and oldword)
    word = oldword + piece if joined else piece
    value = amplitude(piece, word, previous_piece, joined)

    # Punctuation and spaces break runs, including those inside a token.
    tail = re.search(r'[A-Za-z]+$', token)
    if not tail:
        nextword = ''
    elif token.isascii() and token.isalpha():
        nextword = oldword + token
    else:
        nextword = tail.group()
    return (doc, nextword, piece), value

