letters and decimal digits have smaller pulses.  Elsewhere the output
is close to zero, with a correction for nonbreaking spaces and quotes. Token-specific variation
outside these rules is not reconstructed.
"""
READS = ()

# Decimal digits, in their ordinary numerical order.
INITIAL_DIGITS = (-.22, -.47, .06, -.20, -.40,
                  -.27, -.74, -.57, -.43, .08)


def initial_value(text):
    word = text.strip()
    lower = word.lower()
    if word.startswith('/*') and set(word[1:]) == {'*'}:
        if '\n' in text or '\r' in text:
            return .8
        return 1.36 if len(word) > 8 else 2.06 if word == '/**' else 1.68
    if word in ('\"\"\"', "'''"):
        return .68 if '\n' in text else 1.81
    if len(word) >= 8 and set(word) == {'-'}:
        return 1.81
    if lower == 'create':
        return 1.9
    if word in ('void', 'bool', 'boolean'):
        return 1.65
    if word in ('import', 'using', 'package'):
        return 1.0
    if word in ('from', 'class', 'function', 'public', 'int'):
        return .5
    if word.startswith('#'):
        return .33 if word == '#' else .8
    if word == '//':
        return .84
    if word == '<?':
        return 1.08
    if word.startswith('<|'):
        return .3
    if len(word) == 1 and word in '0123456789':
        return INITIAL_DIGITS[int(word)]
    if lower == 'the':
        return .49
    if word == 'A':
        return .45
    if lower == 'a':
        return .13
    if lower == 'an':
        return -.35
    if word == 'I':
        return .4 if text.startswith(' ') else .57
    if lower in ('we', 'they', 'our', 'their', 'you', 'your'):
        return .48
    if lower in ('he', 'she', 'him', 'her', 'me', 'us'):
        return -.3
    if lower in ('to', 'into'):
        return .66
    if lower in ('and', 'or'):
        return .5
    if lower in ('in', 'with'):
        return .05 if word[0].isupper() else .36
    if lower in ('can', 'could', 'will', 'would', 'should', 'may', 'might',
                 'shall', 'must', 'is', 'are'):
        return .35
    if lower in ('have', 'has', 'had', 'was', 'been'):
        return -.22
    if '\t' in text:
        return -.6
    if '\u00a0' in text:
        return -.6
    if word == '.':
        return -.6 if '\n' in text else .24
    if len(word) == 1 and word.isascii() and word.isalpha():
        return .28 if word.isupper() else -.27
    return -.06


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    text = prefix.token_strings[-1]
    if carry is None or carry != doc:
        value = initial_value(text)
    elif '\u00a0' in text:
        value = -.065
    elif text.strip() in ("'", '"', '`'):
        value = .025
    else:
        value = -.003
    return doc, value

