"""Document-start word-class detector for layers.1.mlp.down_proj:1063.

This component is almost silent everywhere except on the first token of a document
(the token right after <|endoftext|>, or the first token of a row), where its value
depends on what kind of token that is:
  - a code or comment opener (slash-star, docstring quotes, #include, import, create,
    select, ...): strongly positive, about +0.9;
  - a common English function word that starts text (The, A, I, You, They, To, From,
    In, ...): mildly positive, about +0.3;
  - a digit, a non-Latin character, or a lowercase word fragment (a word cut mid-way):
    negative, about -0.2 to -0.3;
  - anything else, and every position inside a document: about 0.
"""

CODE_OPENERS = {"/*", "/**", "//", "**", '"""', "```", "<?", "#!/", "#include", "#ifndef",
                "import", "package", "using", "export", "const", "var", "module", "use",
                "continue", "void", "bool", "create", "CREATE", "SELECT", "UPDATE", "JOIN",
                "--------"}
FUNCTION_WORDS = {"The", "A", "I", "You", "They", "We", "He", "She", "It", "His", "Her", "Our",
                  "My", "Your", "This", "There", "To", "From", "As", "In", "On", "At", "By",
                  "With", "For", "Of", "And", "Or", "But", "If", "When", "So", "One", "Are",
                  "Can", "Do", "Use", "How", "What", "Is", "Be", "All", "Any", "Some", "Now",
                  "Here", "Hi"}

READS = ()


def step(carry, prefix, upstream):
    is_doc_start = prefix.position == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]
    if not is_doc_start:
        return None, 0.0
    token = prefix.token_strings[-1]
    word = token.strip()
    if word in CODE_OPENERS:
        return None, 0.9
    if word in FUNCTION_WORDS:
        return None, 0.3
    if word == "" or not word.isascii():
        return None, -0.2
    if word[0].isdigit():
        return None, -0.3
    if word.isalpha() and word.islower() and not token.startswith(" "):
        return None, -0.2
    return None, 0.0

