"""Approximate a printed-indentation detector, not an ordinary space detector.

Tabs mixed with spaces, tabs after digits/spaces, and indentation following
newline escapes or listing/comment/quote markers get positive predictions.
Also recognize nonbreaking-space runs, interpunct separators, and backticks
after HTML-style spaces. Document-initial newline and opening-punctuation
shapes have separate defaults; most word-specific variation is left out.
Only a short current-line buffer is retained, resetting at document changes.
"""
import re

READS = ()
LINE_MARKERS = {'+', '-', '|', '//', '#', '>', "'", '"'}


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    line = '' if first else carry[1]
    marker = line.strip() in LINE_MARKERS
    escaped_newline = line.endswith('\\n')
    spaces, tabs = s.count(' '), s.count('\t')
    horizontal = bool(s) and not s.strip(' \t\xa0')
    value = 0.0

    if first:
        if s in ('\\t', '\\\\t'):
            value = 2.6
        elif '\n' in s:
            value = 1.4 if s.isspace() else 2.2
        elif s.startswith(' ') and s.lstrip().startswith(('"', "'", '“', '‘')):
            value = 2.4
        elif s.startswith(' ') and s.lstrip().startswith(('(', '[', '{')):
            value = 1.8
        else:
            value = -0.1
    elif s in ('\\t', '\\\\t'):
        value = 1.35 if escaped_newline else 1.05
    elif tabs and spaces:
        if s.startswith('   ') and tabs >= 2:
            value = 2.3
        elif spaces <= 4:
            value = 1.65 if spaces <= 2 else 1.93
            if ' ' not in line:
                value = 0.7
        else:
            value = 2.4 if spaces <= 18 else 2.77
    elif tabs:
        if line and line[-1].isdigit():
            if horizontal:
                value = 1.11 if tabs == 1 else 2.19
            else:
                value = 0.7 if s.strip().islower() else 0.18
        elif line.endswith(' '):
            value = 1.87
        elif marker:
            value = 0.9
        elif ' ' in line and len(s) <= 3:
            value = 0.38
    elif horizontal:
        if s.count('\xa0') >= 3:
            value = 1.24
        elif spaces >= 3 and re.fullmatch(
            r'\s*(?:/\*\s*\d+\s*\*/|\d+[:|])\s*', line
        ):
            value = 1.6
        elif spaces >= 3 and (escaped_newline or marker):
            value = 1.0 if spaces == 3 else 1.25
        elif spaces >= 31 and re.fullmatch(r'\s*\d+:?\s*', line):
            value = 2.0
    elif s == '``' and line.endswith('\xa0'):
        value = 1.7
    elif len(s) >= 2 and not s.strip('·'):
        value = 1.36

    line = (line + s).rsplit('\n', 1)[-1][-200:]
    return (doc, line), value

"""Approximate a sparse, local collocation response.

Negative responses mark additive/sequencing adverbs ("and also", "and
then", "or even"), possibility predicates, and several type/test-code
constructions. "See also", clarity/importance predicates and piped grep
have positive responses. These are fitted phrase averages, not a general
semantic analysis. Other contexts get zero; state resets at each document.
"""

READS = ()


def activation(word, previous):
    w, p = word.strip(), previous.strip()
    pl = p.lower()
    # Coordinating, sequencing and cross-referencing expressions.
    if w == 'also':
        if pl == 'see':
            return 3.70
        if pl == 'and':
            return -3.23
        if pl in {'but', 'while'}:
            return -1.22
    if w == 'then' and pl == 'and':
        return -1.80
    if w == 'even' and pl in {'and', 'or'}:
        return -2.30
    if w in {'otherwise', 'consequently', 'therefore', 'yet'} and pl == 'and':
        return -1.01
    if w == 'turn' and pl == 'in':
        return -1.91
    if w == '甚至':  # Chinese "even".
        return -2.95
    if w == '并且' or (w == '且' and p.endswith('并')):
        return -3.65  # Chinese "and also", possibly split across tokens.
    # Possibility, necessity, importance and clarity predicates.
    if w == 'possible':
        if pl == 'it':
            return -4.44
        if pl in {'is', 'be', "'s", '’s', 'very', 'made'}:
            return -1.77
    if pl in {'is', 'be', 'been', "'s", '’s', 'become', 'became'}:
        if w == 'necessary':
            return -1.02
        if w == 'important':
            return 1.19
        if w in {'obvious', 'evident', 'clear', 'apparent'}:
            return 1.57
        if w == 'where':
            return 2.10
    # Explicit type syntax, testing conventions and library names.
    if w == 'Type' and previous == ' :':
        return -7.11
    if w in {'PASS', 'FAIL'} and p.endswith('---'):
        return -2.52
    if w == 'Test':
        if p == '::':
            return -4.48
        if p.endswith('@'):
            return -2.65
        if pl == 'func':
            return -6.89
    if w == '.Test' and p.endswith('junit'):
        return -7.30
    if w == 'Object' and p == ',':
        return -3.31
    if w == 'Exception' and pl == 'throws':
        return -3.45
    if w == '.Text' and p == 'System':
        return -8.64
    if w == 'grep' and p == '|':
        return 2.68
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    word = prefix.token_strings[-1]
    return (doc, word), activation(word, previous)

programs.haiku:
"""Layer 1, MLP down_proj, component 1065: a word-context detector.

Plain-terms summary: this component is mostly quiet, and when it fires it reads the
word just written in light of the word before it. It goes strongly negative on a
discourse adverb that follows "and" or "or" ("and also", "and then", "or even"),
on code names in known spots ("Test" after "::", "Type" after ":"), and on
"possible" after "it"/"is". It goes positive on "also" in "See also", on "where"
or "important"/"clear"/"obvious" after "is", and on the dot-leader "··".

The program needs only the last two tokens, so it is a single pass with no carry.
Values are rough group means measured on training text, not fitted per token.
"""

READS = ()

# Coordinating words that can open a clause-linking adverb.
CONJUNCTIONS = {"and", "or", "And", "Or"}

# Discourse adverbs right after "and"/"or", with typical activation.
ADVERB_AFTER_CONJ = {
    "also": -3.2, "even": -2.3, "then": -1.8, "Then": -1.6,
    "yet": -1.4, "finally": -1.3, "consequently": -1.1, "therefore": -0.8,
}

# Predicate words after "is": "is important" is positive, "is possible" negative.
PREDICATE_POSITIVE = {"important", "clear", "obvious", "evident", "apparent", "sure", "where"}
PREDICATE_NEGATIVE = {"possible", "necessary"}


def step(carry, prefix, upstream):
    toks = prefix.token_strings
    cur = str(toks[-1]).strip()
    prev = str(toks[-2]).strip() if len(toks) > 1 else ""
    v = 0.0
    if cur in ADVERB_AFTER_CONJ and prev in CONJUNCTIONS:
        v = ADVERB_AFTER_CONJ[cur]
    elif cur == "also" and prev == "but":
        v = -1.3
    elif cur == "also" and prev in ("See", "see"):
        v = 3.7
    elif cur == "Type":
        v = -5.4 if prev == ":" else -0.8
    elif cur == "Test" and prev in ("::", "@", "func", "."):
        v = -4.0
    elif cur == "possible" and prev in ("it", "be", "is"):
        v = -2.6
    elif cur in PREDICATE_NEGATIVE and prev == "is":
        v = -1.5
    elif cur in PREDICATE_POSITIVE and prev == "is":
        v = 1.5
    elif cur in ("甚至", "且"):
        v = -2.5
    elif prev == "---":
        v = -1.2
    elif prev == "::":
        v = -0.44
    elif cur == "··":
        v = 0.66
    return carry, float(v)

