"""A surface CAP/KAP detector, not a general detector of hats or ability.

Bare cap, caps, and split c/k + ap have strong positive responses. Longer
capacity/ability spellings are weaker. Transliteration handles some other
scripts; 帽 (hat/cap) has its own response. LaTeX commands are excluded.
Fitted amplitudes approximate the main positive spikes, leaving smaller
background responses unexplained. History resets at document boundaries.
"""
import re
from anyascii import anyascii

READS = ()

# Partial spellings of the CAP family.
FRAGMENTS = {
    'capac': 3.7,
    'capacit': 1.2,
    'capit': 1.7,
    'capita': 1.3,
    'cape': 1.4,
    'capt': 0.7,
}


def response(token, previous, tail):
    s = token.strip()
    w = s.lower()
    spaced = token[:1].isspace()
    if w == '帽':
        return 2.6
    foreign = not s.isascii()
    if foreign:
        w = anyascii(s).lower()
    if w in ('cap', 'caps', 'capped', 'capping'):
        if re.search(r'\\(?:big|Big|bigg|Bigg)?$', tail.rstrip()):
            return 0.0
        if foreign:
            return 1.4
        if w in ('capped', 'capping'):
            return 6.8
        if w == 'caps':
            return 4.6 if spaced else 7.3
        if s.isupper():
            return 4.1 if spaced else 7.7
        if not spaced:
            return 9.0
        # Compounds: market-cap sizes, end caps, ridge caps, keycaps, etc.
        if re.search(r'\b(small|mid|large|end|ridge|key|line)$', tail, re.I):
            return 10.9
        return 6.6
    if w == 'kap':
        return 2.5 if foreign else 4.6
    if w in ('chap', 'cab', 'cabe'):
        return 1.5
    if w == 'recap':
        return 3.3
    if w in ('incap', 'incapac'):
        return 4.2
    if w.endswith('cap') and w[:-3] in ('i', '-', '_', '.', '('):
        return 7.1
    if w.startswith('capabil'):
        return 3.8 if w.endswith('ies') else 3.1
    if w == 'capable':
        return 2.7
    if w == 'incapable':
        return 2.0
    if w in ('capacity', 'capacities', 'capacitor'):
        return 0.6
    if w in FRAGMENTS:
        return FRAGMENTS[w]
    if w in ('capacidad', 'capacite', 'capacita'):
        return 1.8
    if not spaced and previous:
        p = anyascii(previous).lower()
        if w.startswith('ap') and re.search(r'\\[a-zA-Z]*$', tail):
            return 0.0
        if p.endswith(('c', 'k', 'ch')):
            if w.startswith('ap'):
                if p.endswith('ch'):
                    return 3.2
                if w in ('ap', 'aps', 'app', 'apped', 'apping', 'apper'):
                    return 8.6
                if w in ('ape', 'apes', 'aped', 'apt'):
                    return 2.0
                return 1.6
            if w in ('ab', 'abe', 'ao', 'aff'):
                return 1.1
        if p.endswith(('cap', 'kap')):
            if w.startswith('abil'):
                return 6.7
            if w in ('able', 'ables'):
                return 4.2
            if w in ('a', 'o', 'az', 'aces'):
                return 2.8
            if w in ('ac', 'it'):
                return 1.7
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous, tail = ('', '') if carry is None or carry[0] != doc else carry[1:]
    token = prefix.token_strings[-1]
    value = 1.1 * response(token, previous, tail)
    return (doc, token, (tail + token)[-64:]), value

