"""layers.1.mlp.down_proj:1066 explained: a detector for the English word "cap".

The component lights up on the letters c-a-p spelled as a word or word piece:
  * the token "cap", " cap", "Cap", " Cap", "CAP", "_CAP", "icap", "-cap": about 7;
  * "caps", "capped", and "kap" (as in Handikap, Kap): about 5 to 7;
  * a "cap" that is a noun after a size or position word (mid cap, small cap,
    super cap, end cap, ridge cap): about 12, the strongest case;
  * a "cap" completed across tokens, such as "c" + "ap" in "capping": about 7;
  * "capable", "capability", "capabilities": about 3;
  * the Chinese word 帽 (cap, hat): about 3.
It is off for LaTeX intersection (\\cap, preceded by a backslash), and near zero for
other "cap" words such as "capacity", "capital", "capture" and "escape".

The program tracks the letters of the current word (carry), and reads the previous
token only to check for a backslash or a size word. It has no table of token ids.
"""
import re

READS = ()

SIZE_WORDS = {"mid", "small", "large", "super", "micro", "end", "ridge"}


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    new_doc = len(prefix.token_strings) == 1 or prefix.document_ids[-1] != prefix.document_ids[-2]
    prev = "" if new_doc else prefix.token_strings[-2]
    # letters of the current word so far, lowercase: a token with no leading space
    # that is all letters continues the word; otherwise the word restarts here
    word = "" if (carry is None or new_doc) else carry
    tail = re.search(r"[A-Za-z]*$", tok).group(0)
    word = (word + tail if tail == tok and not tok.startswith(" ") else tail).lower()
    low = tok.strip().lower()
    if prev.endswith("\\"):  # LaTeX \cap (intersection), not the word
        value = 0.0
    elif word.endswith("cap"):
        size = prev.strip().lower() in SIZE_WORDS
        value = 12.0 if size else 7.0
    elif word.endswith("kap") or low in ("caps", "capped"):
        value = 6.0
    elif not tok.startswith(" ") and tok.startswith("ap") and prev.endswith(("c", "k")):
        value = 6.0  # "c" + "apped", "k" + "ap": the cap sound across a token boundary
    elif low.startswith("capab") or low.startswith("capable"):
        value = 3.0
    elif "帽" in tok:
        value = 3.0
    else:
        value = 0.0
    return word, value

