"""Approximate a markup-attribute and boilerplate-boundary response.

Attribute names inside open HTML/XML/JSX tags are positive, especially
'name' in <param>. Quoted command/arguments keys, a Sphinx version
marker, and wiki-table style fields have smaller positive responses.
Selected forum metadata, single-quote record punctuation, /usr/bin/env,
and a hexadecimal escape after an escaped newline are negative.

Document starts get a positive average, larger for English content words
with no noun reading in WordNet. Other text usually gets zero: this does
not attempt to reproduce the remaining individual-word variation.
A bounded text tail supplies syntax and resets at document boundaries.
"""
import re
import wordnet

READS = ()

# Standard HTML/XML attribute roles, rather than vocabulary token IDs.
ATTRIBUTES = {
    'name': 1.45, 'class': 2.05, 'className': 1.55,
    'id': 1.7, 'align': 2.4, 'target': 2.2, 'href': 1.9,
    'rel': 1.5, 'type': 1.2, 'value': 1.0, 'style': 1.2,
    'title': 0.8, 'src': 1.0, 'xmlns': 1.9, 'for': 1.7,
    'data': 1.0, 'colspan': 1.0, 'rowspan': 0.7,
    'width': 0.7, 'height': 0.7, 'ref': 0.8, 'label': 0.5,
    'default': 0.5, 'placeholder': 0.7,
    'onClick': 1.0, 'onChange': 0.6, 'onclick': 1.4,
    'selected': 1.1, 'checked': 0.6, 'disabled': 0.5,
}
TAG = re.compile(r'(?:<|&lt;)([A-Za-z][\w:.-]*)([^<>]*)$')
# The preceding text must be complete attributes, not a comparison or a
# still-open quoted attribute value. Also accept JSX brace expressions.
ATTRIBUTE_TAIL = re.compile(
    r"""(?:\s+[\w:.-]+(?:\s*=\s*(?:"[^"]*"|'[^']*'|"""
    r"""\{[^{}]*\}|[^\s\"'{}=<>]+))?)*\s*"""
)


def predict(s, tail, first):
    word = s.strip()
    if s[:1].isspace() and word in ATTRIBUTES:
        tag = TAG.search(tail.replace('\\\"', '\"'))
        if tag and ATTRIBUTE_TAIL.fullmatch(tag[2]):
            if word == 'name' and tag[1] in ('param', 'typeparam'):
                return 3.55
            if word == 'value' and tag[1] == 'option' and not tag[2].strip():
                return 2.7
            return ATTRIBUTES[word]
    if s == ':' and tail.rstrip().endswith('Joined'):
        return -1.6
    if s == ' given' and re.search(r'\]\s*,\s*$', tail):
        return -1.8
    if (s in (' points', ' point')
            and re.search(r'(?:\n|\])\s*[-–]?\s*\d+$', tail)):
        return -1.0
    if s == '\\x':
        return -2.0 if re.search(r'\\n\s*$', tail) else 0.2
    if s in ('command', 'arguments') and tail.endswith('"'):
        return 0.29
    if s == '/env' and tail.endswith('/usr/bin'):
        return -1.7
    if s == ' version' and tail.rstrip().endswith('..'):
        return 1.7
    if s == ' style' and tail.rstrip().endswith('|'):
        return 0.6
    if s == " ':" or s == "':":
        return -0.3
    if s == " '" and tail.rstrip().endswith(','):
        return -0.18
    if first:
        if word.isascii() and word.isalpha():
            parts = wordnet.parts_of_speech(word.lower())
            if parts and 'noun' not in parts:
                return 0.55
            if parts == {'noun'}:
                return 0.22
        return 0.25
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        tail = ''
    else:
        tail = carry[1]
    s = prefix.token_strings[-1]
    value = predict(s, tail, not tail)
    return (doc, (tail + s)[-500:]), value

