        st["mode"] == "attrs" or s[:1].isspace()
    ):
        value = FIRST_ATTR if st["nattr"] == 0 else LATER_ATTR
        st["nattr"] += 1
    for ch in s:
        prev = st["last"]
        st["last"] = ch
        if st["quote"] is not None:
            if ch == st["quote"]:
                st["quote"] = None
                st["mode"] = "attrs"
            continue
        if st["pending"] and ch.isalpha() and ch.islower():
            st["in_tag"], st["mode"], st["pending"], st["nattr"] = True, "tagname", False, 0
            continue
        st["pending"] = False
        if ch == "<":
            st["in_tag"], st["mode"] = False, "none"
            st["pending"] = not (prev.isalnum() or prev == "_")
        elif not st["in_tag"]:
            continue
        elif ch == ">":
            st["in_tag"], st["mode"] = False, "none"
        elif ch in "\"'":
            st["quote"] = ch
        elif ch == "=":
            st["mode"] = "value"
        elif ch.isspace():
            if st["mode"] in ("tagname", "value"):
                st["mode"] = "attrs"
        elif st["mode"] == "tagname" and TAGCHAR.match(ch):
            pass
        elif st["mode"] == "attrs" and ATTRCHAR.match(ch):
            pass
        elif ch == "/":
            st["mode"] = "none"
        else:
            st["in_tag"], st["mode"] = False, "none"
    return st, value

