"""Sparse surface-pattern approximation, not a full activation reconstruction.

Predict digit pairs 30/31, stronger after month names or slash-date prefixes
and weaker within longer integers, plus 19 and the written number thirty.
Recognize short/shortly, German kurz and its adjective endings, forum profile
headings, and escaped-tab runs. Other text gets a near-zero baseline with a
small first-token offset. Bounded state resets at document boundaries.
"""
import calendar
import re

READS = ()
_MONTHS = set(calendar.month_name[1:]) | set(calendar.month_abbr[1:])
_MONTH = re.compile(r'\b(?:' + '|'.join(_MONTHS) + r')\.?\s*$', re.I)
_NUMBER = re.compile(r'[0-9]+$')
_SLASH_DATE = re.compile(r'\d{1,2}/$')
_SHORT_WORD = re.compile(r'\b(short|shortly|thirty|kurz(?:e[nmrs]?)?)$', re.I)
_PROFILE = re.compile(r'(?:^|\n)(?:Posts|Joined|Location)$')


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', 0, True, '')
    _, text, position, tabs_only, last = carry
    token = prefix.token_strings[-1]
    value = -0.0004 + (0.06 if position == 0 else 0.0)

    # Numeral prefixes: the second digit of 30, 31, or 19.
    if token in ('0', '1') and text.endswith('3'):
        run = _NUMBER.search(text).group()
        if len(run) == 1:
            value += 0.36 if token == '0' else 0.24
            before = text[:-1]
            if _MONTH.search(before):
                value += 0.44
            if _SLASH_DATE.search(before):
                value += 0.20
        else:
            value += 0.16 if token == '0' else 0.09
    if token == '9' and text.endswith('1'):
        value += 0.056

    # English shortness words, the written numeral thirty, and German kurz.
    word = _SHORT_WORD.search(text + token)
    if word:
        word = word.group().lower()
        if word == 'thirty':
            value += 0.22
        elif word == 'shortly':
            value += 0.49
        elif word == 'short':
            value += 0.10
        else:
            value += 0.83

    # Forum profile headings and the colon immediately following them.
    if token in ('Posts', 'Joined', 'Location'):
        if not text or text.endswith('\n'):
            value += 0.105
    if token == ':' and _PROFILE.search(text):
        value += 0.125

    # Escaped indentation is unusually strong at a document's beginning.
    if token == '\\t':
        if tabs_only:
            value = 1.498
        elif last == '\\t':
            value += 0.046

    state = (doc, (text + token)[-100:], position + 1,
             tabs_only and token == '\\t', token)
    return state, float(value)

"""A coarse opening-position and first-item response.

Usually zero. Document openings use script, typography, word frequency,
function-word classes, programming keywords, and broad WordNet noun classes.
Common capitalized sentence openers tend negative; indentation and code
openers tend positive. Later rules recognize first list labels, arithmetic,
iteration/membership, test descriptions, and shell here-document openings.
Repeated opening filler and an opening '12' have explicit exceptional rules.
Class averages deliberately omit token-specific opening values and most
small contextual fluctuations. State resets at each document boundary.
"""
from functools import lru_cache
import re
import regex
from wordfreq import zipf_frequency
import wordnet

READS = ()

PRONOUNS = set('i you he she it we they my your his her our their'.split())
DETERMINERS = set('a an the this that these those each every any some all'.split())
LINK_WORDS = set('in on at by to for from with as if while when after before'.split())
QUESTIONS = set('how why what which who where'.split())
TYPE_WORDS = set(
    'int integer uint float double char string str bool boolean byte void object'
    .split()
)
DECLARATIONS = set(
    'def function class struct enum interface namespace typedef var let const type'
    .split()
)


@lru_cache(maxsize=8192)
def opening_value(s):
    w = s.strip()
    low = w.lower()
    if w == '<|endoftext|>':
        return -5.0
    if w.startswith('<|'):
        return 2.19
    if not w:
        if s.strip(' \t'):
            return 0.43
        return 1.06 if len(s) == 1 else 3.72
    if w.isdigit():
        return -1.68 if w == '0' else 1.11
    if regex.search(r'[\p{Script=Han}\p{Script=Hiragana}\p{Script=Katakana}]', w):
        return 2.23
    if w.isalpha():
        if not w.isascii():
            return 0.89
        if w in TYPE_WORDS:
            return 4.67
        if w in DECLARATIONS:
            return 5.72
        if not s.startswith(' ') and w.istitle():
            for words, response in ((PRONOUNS, -2.15),
                                (DETERMINERS, -0.72),
                                (LINK_WORDS, -2.14),
                                (QUESTIONS, -2.96)):
                if low in words:
                    return response
        freq = zipf_frequency(low, 'en')
        if freq >= 6:
            if w.istitle() and not s.startswith(' '):
                return -0.7
            return 0.35
        if w.istitle() and len(w) <= 3 and not s.startswith(' '):
            return 0.21
        cats = wordnet.categories(low)
        if cats.intersection({'noun.person', 'noun.artifact', 'noun.cognition',
                              'noun.attribute', 'noun.object'}):
            return 1.95
        return 1.36 if len(w) >= 5 else 1.48
    if w.startswith(('.', ',')):
        return 0.64
    if w.startswith((')', ']', '}')):
        return 2.18
    if w.startswith('*'):
        return 2.97
    return 1.21


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    s = prefix.token_strings[-1]
    w = s.strip()
    if carry is None or carry[0] != doc:
        n, first, same, tail = 0, s, True, ''
    else:
        _, n, first, same, tail = carry
        same = same and s == first
    before = tail.rstrip()
    context = tail.replace('\\n', '\n').replace('\\t', '\t')
    line = context.rsplit('\n', 1)[-1]
    value = 0.0
    # Repeated decorative filler at the beginning of a document.
    if same and s == '\r':
        value = -8.6
    elif same and len(s) >= 2 and len(set(s)) == 1 and s[0] in '·^':
        value = -6.0
    elif n == 0:
        value = opening_value(s)
    elif n == 1 and first == '1' and w == '2':
        # The second digit of an opening "12" is an unusually strong exception.
        value = -22.7
    elif same and w == '0':
        value = -1.68
    elif w == '1' and not line.strip():
        value = 0.75 if re.search(r'(?::|：|\n[ \t]*\n)\s*$', context) else 0.15
    elif w in {'.', ')', '）', '、', '．', ']'} and re.fullmatch(
            r'[ \t>*#]*[（(\[]?1', line):
        value = 0.9
    elif w in {'.', ')', '）', '、', ':'} and re.fullmatch(
            r'[ \t>*#]*[（(]?[aAiI]', line):
        value = 0.7
    elif w in {'-', '*', '•', '·', '・'} and not line.strip():
        value = 0.6 if re.search(r'(?::|：|\n[ \t]*\n)\s*$', context) else 0.05
    elif w in {'+', '-', '−'}:
        # Arithmetic lines have short variable names or explicit math notation.
        words = re.findall(r'[A-Za-z]+', line)
        math = (re.search(r'[=$^²³α-ωΑ-Ω]', line) or
                (all(len(word) <= 3 for word in words) and
                 re.search(r'[0-9A-Za-z]', line)))
        if math and not re.search(r'[";]', line):
            value = 0.55 if w == '+' else 0.5
        elif w == '+':
            value = 0.05
    elif w == 'in' and re.fullmatch(
            r'\s*(?:async +)?for +\w+(?: *, *\w+)* *', line):
        value = 1.5
    elif w == ':' and re.fullmatch(
            r'\s*(?:for|foreach) *\([^;:()]{1,80}', line):
        value = 1.0
    elif w == 'range' and re.fullmatch(
            r'\s*for +[^;\n]{1,80}:= *', line):
        value = 1.4
    elif w == '∈' or (w == 'in' and before.endswith('\\')):
        value = 0.9
    # Quoted test descriptions and shell here-document openings.
    elif w.startswith(('("', "('", '(`')) and re.search(
            r'\b(?:it|test|describe|suite) *$', line):
        value = 1.0
    elif w == 'EOF' and re.search(r'''<<<?[ \\"']*$''', line):
        value = 2.0
    elif w in {"'", '"', '\\"'} and re.search(
            r'''(?:<<| -[ceE]| -i) *$''', line):
        value = 0.75
    elif '\n' in s and re.search(r'''<<[^\n]*EOF[ \\"']*$''', line):
        value = 1.1
    return (doc, n + 1, first, same, (tail + s)[-180:]), float(value)

"""International institutions, formal agreements, and descriptive settings.

Negative responses are attached to geopolitical vocabulary and familiar
institutional compounds (Member States, United Nations, working group).
Clinical-study compounds and several common discourse words are also negative.
Chinese dictionary glosses recognize some of the same international concepts.
Descriptions of a local setting are mildly positive, as are middle-dot runs.
Only a short text tail is carried; document boundaries reset it.
"""
import regex as re
from functools import lru_cache
import cedict

READS = ()

GLOBAL_TERMS = {
    'country': -0.74, 'countries': -1.5, 'nation': -0.4, 'nations': -0.6,
    'world': -0.25, 'international': -0.8, 'internationally': -1.0,
    'worldwide': -0.8, 'global': -1.0, 'globally': -1.0,
    'bilateral': -1.8, 'multilateral': -1.8, 'european': -0.8,
    'national': -0.3,
}
BODIES = set('UN EU OECD UNESCO UNICEF UNDP UNHCR NATO WTO IMF ILO IMO'.split())
AGREEMENTS = set('treaty treaties declaration annex signatories'.split())
GOVERNANCE = set('''commission council parliament governance minister ministers
    ambassador ambassadors authorities'''.split())
COOPERATION = set('''cooperation donor donors economies stakeholders programme
    assistance assessment delegation conference convention'''.split())
SETTING = set('''environment surroundings location locations scene scenario
    scenarios situation situations appearance experiences'''.split())

# Strength comes from the whole conventional expression, not just its last word.
PHRASES = {
    'united nations': -4.0, 'united states': 0.22, 'member states': -5.6,
    'working group': -3.8, 'capacity building': -2.3,
    'sustainable development': -1.7, 'development goals': -5.5,
    'kyoto protocol': -4.5, 'montreal protocol': -4.0,
    'european parliament': -3.2, 'european council': -3.7,
    'european commission': -1.6, 'european union': -1.5,
    'security council': -2.4, 'general assembly': -2.5,
    'trade organization': -2.7, 'labor organization': -2.7,
    'labour organization': -2.7, 'health organization': -2.7,
    'human rights': -1.1, 'value chains': -1.8,
    'prime minister': -0.8, 'prime ministers': -1.4,
    'olympic games': -2.5, 'world cup': -1.3,
    'trade agreements': -2.0, 'trade capacity': -0.9,
    'clinical trial': -1.9, 'clinical trials': -2.5,
    'controlled trial': -2.0, 'controlled trials': -2.5,
    'systematic review': -1.6, 'in particular': -1.0,
    'randomized trial': -1.9, 'randomised trial': -1.9,
}
RELATIONAL = set('''goal goals aim aims objective objectives framework
    target targets assessment need code court'''.split())


@lru_cache(maxsize=8192)
def han_concept(word):
    """Recognize the same international concepts by dictionary gloss."""
    gloss = '; '.join(cedict.glosses(word)).lower()
    if 'united nations' in gloss:
        return -5.0 if 'security council' in gloss else -1.8
    if 'european union' in gloss:
        return -1.9
    if 'international' in gloss:
        return -0.95
    if 'worldwide' in gloss or 'global' in gloss:
        return -0.6
    if gloss in ('world', 'the world'):
        return -0.5
    if 'treaty' in gloss:
        return -1.8
    return None


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tail = '' if carry is None or carry[0] != doc else carry[1]
    token = prefix.token_strings[-1]
    text = (tail + token)[-120:]
    raw = token.strip()
    latin = bool(raw and raw[-1].isascii() and raw[-1].isalpha())
    spellings = re.findall(r'[A-Za-z]+', text)
    surface = spellings[-1] if latin else raw
    word = surface.lower()
    words = [w.lower() for w in spellings]
    value = GLOBAL_TERMS.get(word, 0.0)
    if surface in BODIES:
        value = -1.9
    if word in AGREEMENTS:
        value = -1.8
    if word in GOVERNANCE:
        value = -0.7
    if word in COOPERATION:
        value = -0.6
    if word in SETTING:
        value = 0.45
    if word in ('parties', 'party'):
        value = -0.8 if word == 'parties' else -0.15
    if word == 'trials':
        value = -1.0
    if surface == 'Parties':
        value = -2.0
    if word in ('also', 'already', 'under', 'instance'):
        value = -0.26
    if surface == 'World':
        value = -0.8
    if surface == 'Global':
        value = -1.6
    if surface == 'United':
        value = 0.26
    if len(words) >= 2 and latin:
        prev = words[-2]
        pair = ' '.join(words[-2:])
        value = PHRASES.get(pair, value)
        if surface in BODIES and prev == 'the':
            value = -3.5 if surface == 'UN' else -2.0
        if word in ('country', 'countries', 'world'):
            if prev in ('developing', 'recipient', 'donor', 'emerging'):
                value = -3.2 if prev != 'recipient' else -5.0
            elif word == 'world':
                if prev in ('natural', 'corporate', 'programming', 'virtual', 'real'):
                    value = 1.0
                elif prev == 'the':
                    value = -1.8 if surface == 'World' else -0.9
        if word == 'european' and prev == 'the':
            value = -1.5
        if word == 'also' and prev in (
            'is', 'are', 'was', 'will', 'can', 'but', 'and', 'it'
        ):
            value = -0.42
        if word == 'already' and prev in ('is', 'are', 'was', 'has', 'have'):
            value = -0.6
        if word == 'of':
            if prev in RELATIONAL:
                value = -0.65
            elif prev in SETTING or prev == 'world':
                value = 1.5
        if word == 'on' and prev in ('information', 'report', 'literature'):
            value = -0.75
        if surface == 'Member' and prev == 'the':
            value = -2.8
    # Cognates often finish in a separate subword token.
    if words and re.fullmatch(r'internation[a-z]*', words[-1]) and latin:
        value = -0.8
