    if han:
        ending = han[0][-5:]
        for width in range(len(ending), 1, -1):
            translated = han_concept(ending[-width:])
            if translated is not None:
                value = translated
                break
    if '国際' in token:
        value = -0.95
    if raw == 'CI' and '%' in tail[-12:]:
        value = -1.75
    if len(raw) >= 2 and set(raw) == {'·'}:
        value = 1.8
    return (doc, text), value

"""Spelling-sensitive WILL/WOULD and HAVE responses.

WILL and WOULD are positive, especially capitalized or split after W.
Their strength also depends on grammatical person: 'we will' is weaker
than 'it will'. HAVE is weak after modals/infinitival TO, stronger after
an overt subject. Related Germanic auxiliaries and W+vowel+L spellings
also respond. Selected WA/WAR/WOR spellings and Japanese WA are negative.
Non-ASCII V+vowel+L continuations are recognized by transliteration.
This is a lexical approximation; it does not try to parse a sentence.
"""
import re
from anyascii import anyascii

READS = ()

HAVE = {
    'habe': .93, 'haben': .93, 'hat': .68, 'hatte': 1.0,
    'hatten': 1.0, 'hätte': 1.0, 'ha': .91, 'han': .99,
    'har': .66, 'ho': .46, 'hanno': 1.3,
    'ont': .85, 'avait': 1.49, 'avons': 1.4,
}
GERMAN = set('der die das und nicht ich ein eine sich mit von den dem '
             'es ist auf aus zu als wenn noch nun zum uns'.split())
PERSONAL = set('i we you he she they'.split())
MODALS = set('will would shall should can could may might must'.split())
ADVERBS = set('not also only still already never just'.split())
POSSESSIVE = set('my your his her its our their'.split())


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous, german, tail = (('', 0., '') if carry is None or carry[0] != doc
                              else carry[1:])
    token = prefix.token_strings[-1]
    word = token.strip()
    lower = word.lower()
    prev = previous.strip().lower()
    spaced = token.startswith(' ')
    capital = word != lower
    value = 0.0

    if lower == 'will':
        value = 2.35
        if not spaced or capital:
            value = 5.1
        elif german > 1.5 or (previous.startswith(' ')
                              and prev in ('er', 'sie', 'wir')):
            value = 6.2
        elif prev in POSSESSIVE or prev in ('the', 'a', 'at', 'free', 'good'):
            value = 5.3
        elif prev in ('i', 'we', 'you', 'they'):
            value = {'i': 1.35, 'we': 1., 'you': 1.55, 'they': 1.85}[prev]
        elif prev in ('he', 'she', 'this', 'which'):
            value = 2.
        elif prev == 'that':
            value = 1.8
        elif prev in ('it', 'there'):
            value = 2.65
        elif prev in ('what', 'why', 'how', 'when', 'where'):
            value = 3.6
    elif lower == 'would':
        value = .85 if prev in PERSONAL else 1.5
        if not spaced or capital:
            value = 2.7
        elif prev in ('what', 'why', 'how', 'when', 'where'):
            value = 2.7
    elif lower in ('wil', 'wilt', 'vill'):
        value = 1.9 if capital and lower == 'vill' else 6.5
    elif lower == 'vil':
        value = 1.6 if capital else 3.4
    elif lower in ('woll', 'wolle', 'wollte'):
        value = 5.1
    elif lower in ('wollen', 'willen', 'würde', 'wür', 'möchte'):
        value = 3.3
    elif lower in ('wird', 'werde'):
        value = 1.65
    elif lower == 'werden':
        value = 1.07
    elif lower.startswith(('wild', 'wald')):
        value = 3.1 if capital or not spaced else 2.3
    elif lower.startswith('will'):
        value = 1.
    elif lower in ('wol', 'wool'):
        value = 1.8
    elif lower in ('have', 'has', 'had'):
        value = .55
        if lower == 'have':
            if prev == 'i':
                value = .95
            elif prev in MODALS or prev in ADVERBS or prev in ('to', "'t", '’t'):
                value = 0.
        elif lower == 'has':
            value = .75 if prev in ('he', 'she', 'who', 'there') else .4
            if prev in ADVERBS or prev.isdigit():
                value = 0.
        else:
            value = .9 if prev in ('i', 'he', 'she') else .6
            if prev in ('have', 'has', 'had') or prev in ADVERBS:
                value = .25
    elif lower in HAVE:
        value = HAVE[lower]
    elif lower in ("'ve", '’ve'):
        value = 1.12
    elif lower in ("'ll", '’ll', "'d", '’d'):
        value = .68
    elif lower in ('wa', 'wah', 'wax', 'wart', 'worry', 'warm'):
        value = -1.5
    elif word.startswith('わ'):
        value = -2.5
    elif word.startswith('ワ'):
        value = -1.9

    # Recognize syllables split across tokens, but never across words.
    if token[:1].isalpha() and tail:
        old = tail.lower()
        if old.endswith('w'):
            if len(lower) <= 4 and re.match(r'a(rt|x|rn)', lower):
                value = -4.8
            elif re.match(r'[iou]{1,2}l($|l|[^aeiou])', lower):
                value = 9. if lower in ('il', 'ill', 'ilt') else 5.6
            elif lower.startswith(('ü', 'ö')):
                value = 3.8
            elif lower[:1] in 'ieouy' and lower.isalpha():
                value = 1.4
        elif re.search(r'w[ieouy]{1,2}l?$', old) and lower.startswith('l'):
            value = 4.5
        elif re.search(r'w[üö][rl]$', old) and lower[:1] in 'dtl':
            value = 4.2
        elif not old.isascii():
            # Non-ASCII spellings: transliterated V + vowel + L.
            if anyascii(old).lower().endswith('v'):
                if re.match(r'[iou]l', anyascii(lower).lower()):
                    value = 3.4

    # Keep only the unfinished word, and a decaying German-language cue.
    letters = re.search(r'[^\W\d_]+$', token)
    if letters is None:
        tail = ''
    elif letters.start() == 0:
        tail = (tail + token)[-24:]
    else:
        tail = letters.group()[-24:]
    german = .99 * german + (lower in GERMAN)
    german += any(c in 'äöüßÄÖÜ' for c in word)
    return (doc, token, german, tail), value

programs.haiku:
"""Candidate 6: auxiliary verbs of the will/would and have families, several languages.

Fires on the finite auxiliary that carries future, conditional or perfect tense after its
subject: English will/would and have/has/had (and 'll, 've, 'd), German wird/werden/würde/
wollte and hat/haben/hatte, French/Italian/Spanish have-auxiliaries, Norwegian/Dutch vil/wil.
Strongest on "will" (2-5 nats), weaker on "would" and "have/has/had" (0.4-1). It stays
silent on other words and on infinitive "have" (after to/modals/not), which is near zero.
Spelling fragments of "will" (Wil, wil, vil, wild) also fire, and capitalised forms are
stronger than lower-case ones.
"""
READS = ()

WILL = {"will": 2.3, "wollte": 5.0, "würde": 3.5, "wird": 1.7, "werden": 1.1, "vil": 3.5,
        "wil": 6.0, "wild": 2.2, "would": 1.4}
HAVE = {"have": 0.6, "has": 0.5, "had": 0.7, "hat": 0.7, "haben": 0.9, "hatte": 0.9,
        "hast": 1.0, "habe": 0.9, "hätte": 0.5, "avons": 1.4, "avez": 1.1, "ont": 1.0,
        "hanno": 1.3, "abbiamo": 1.3, "ha": 0.8, "han": 1.0, "había": 1.0, "ho": 0.7,
        "'ve": 1.1, "’ve": 1.2, "'ll": 0.7, "’ll": 0.6, "'d": 0.7, "’d": 0.8}
NON_FINITE = {"to", "not", "'t", "’t", "never", "also", "would", "will", "should", "can",
              "may", "must", "might", "could", "shall", "always", "only", "just", "still"}


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1].strip()
    tok = raw.lower()
    prev = prefix.token_strings[-2].strip().lower() if len(prefix.token_strings) > 1 else ""
    if tok in WILL:
        value = WILL[tok]
        if len(raw) > 1 and raw[0].isupper():
            value *= 2.0
        return None, float(value)
    if tok in HAVE:
        if tok in ("have", "has", "had") and prev in NON_FINITE:
            return None, 0.0
        return None, float(HAVE[tok])
    return None, 0.0

programs.sol:
"""Number and possession signals near the English definite article.

Plural nouns shortly after 'the' get positive values, stronger for people
and weaker for rare words. A following connective inherits some of this
signal. Possessive endings and relative-location words get negative values.
Effects decay with token distance; case and word classes give small
first-word corrections. WordNet, inflect and wordfreq provide the linguistic
rules and dictionaries. They do not contain learned component activations.
"""
from functools import lru_cache
import wordnet
import inflect
from wordfreq import zipf_frequency

_INFLECTION = inflect.engine()

READS = ()

CONNECTORS = frozenset('''
of in on at for from to with by and or that which who are were have do
is was has does as than about
'''.split())
FUNCTION_WORDS = CONNECTORS | frozenset('''
the a an this these those it its his her their our your my be been being
will would may can could should not no all each any more most other some
such same
'''.split())


@lru_cache(maxsize=32768)
def plural_word(word):
    w = word.lower()
    if w in FUNCTION_WORDS or not w.isascii() or not w.isalpha():
        return False
    bases = wordnet.base_forms(w, 'noun')
    if any(b != w for b in bases):
        return True
    if not w.endswith('s'):
        return bool(_INFLECTION.singular_noun(w))
    if w.endswith(('ss', 'ous', 'ics', 'ness')):
        return False
    return not wordnet.parts_of_speech(w)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, 100, '', False)
    _, distance, word, was_plural = carry
    distance += 1
    token = prefix.token_strings[-1]
    stripped = token.strip()
    if stripped == 's' and word in ("'", '’'):
        word += stripped
    elif token[:1].isspace() or not word.isalpha() or not stripped.isalpha():
        word = stripped
    else:
        word += stripped
    w = word.lower()
    plural = plural_word(word)
    value = -.003
    if w in ('above', 'below', 'before', 'after'):
        value -= .073
    if 1 <= distance <= 6:
        value += (0, .071, .048, .024, .016, .008, .007)[distance]
        if plural:
            value += (0, .40, .27, .14, .04, .04, .04)[distance]
            if distance <= 2 and 'noun.person' in wordnet.categories(w, 'noun'):
                value += .19 if distance == 1 else .16
            if distance == 1 and 0 < zipf_frequency(w, 'en') < 3:
                value -= .24
        if w in ("'s", '’s'):
            value -= (0, 0, .862, .601, .084, .084, .084)[distance]
        if w in ('above', 'below', 'before', 'after'):
            value -= (0, .295, .402, .234, .064, .064, .064)[distance]
        if was_plural:
            value += (0, 0, .052, .068, .027, .027, .027)[distance]
            if w in CONNECTORS:
                value += (0, 0, .214, .145, .044, .044, .044)[distance]
        if distance == 1:
            parts = wordnet.parts_of_speech(w)
            if 'noun' in parts and not plural:
                value -= .059
            if 'adjective' in parts:
                value -= .035
            if word[:1].isupper():
                value -= .07
            if not parts and w not in FUNCTION_WORDS and w.isalpha():
                value -= .043
    if w == 'the':
        distance = 0
    return (doc, distance, word, plural), float(value)

"""Approximate the component's spelling-sensitive document-start impulse.

After the first token of a document, predict zero. At the start, two-character
or shorter e-final pieces get a negative value and b/p-final pieces a positive
one. Longer pieces get positive values unless very common English words;
d/t endings increase the estimate. Bare code openers, import keywords and
special markers get negative values. These are broad fitted averages, not
exact word-specific responses.
"""
from wordfreq import zipf_frequency

READS = ()
# Exact syntax: spaces or a newline would make a different token fragment.
CODE_OPENERS = frozenset({'//', '/*', '<?'})
MODULE_IMPORTS = frozenset({
    'import', 'package', 'using', 'from', '#include',
})


def step(carry, prefix, upstream):
    first = (prefix.position == 0 or
             prefix.document_ids[-1] != prefix.document_ids[-2])
    if not first:
        return None, 0.0
    raw = prefix.token_strings[-1]
    if raw in CODE_OPENERS:
        return None, -6.5
    if raw in MODULE_IMPORTS:
        return None, -2.5
    token = raw.strip().lower()
    if token.startswith('<|'):
        return None, -6.0 if token == '<|endoftext|>' else -0.3
    if len(token) <= 2:
        if token.endswith('e'):
            value = -4.1
        elif token.endswith(('b', 'p')):
            value = 4.4
        else:
            value = -0.3
    elif (token.isascii() and token.isalpha() and
          zipf_frequency(token, 'en') > 6.4):
        value = -0.7
    else:
        value = 2.4 if token.endswith(('d', 't')) else 1.0
    return None, value

"""A lexical and grammatical approximation, strongest on forms of 'become'.

It gives negative values to becoming/overcoming, especially after auxiliaries
or infinitival 'to'. It also recognizes words assembled across token boundaries.
Positive values mark 'be able' and preposition + reflexive constructions. Most
other text is assigned zero. Split be-words receive weaker dictionary-based
noun/adjective or productive be-verb corrections. The split German Beobacht-
(observe) stem receives a strong positive correction. These rules approximate
only some of the component's responses to unusual be-word fragments.
"""
import re
import wordnet
from functools import lru_cache


@lru_cache(maxsize=2048)
def be_word_value(word, at_prefix):
    """Distinguish nominal be-words from verbs formed with the prefix be-."""
    pos = wordnet.parts_of_speech(word)
    if at_prefix and ('noun' in pos or 'adjective' in pos):
        return 1.5
    # A productive be-verb, with a verb root remaining after removing be-.
    root_pos = wordnet.parts_of_speech(word[2:])
    if 'verb' in pos and 'verb' in root_pos:
        return -2.5
    return 0.0

READS = ()
AUXILIARIES = {'has', 'had', 'having', 'can', 'not'}
MODALS = {'will', 'would', 'could', 'should', 'must', 'shall', 'might'}
PREPOSITIONS = {
    'of', 'for', 'from', 'to', 'after', 'before', 'by', 'with',
    'without', 'despite', 'upon', 'in', 'on', 'under', 'except',
}
REFLEXIVES = {
    'myself', 'yourself', 'himself', 'herself', 'itself',
    'ourselves', 'yourselves', 'themselves', 'oneself',
}
BECOME = {'become', 'became', 'becomes', 'becoming'}
OVERCOME = {'overcome', 'overcame', 'overcomes', 'overcoming'}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        previous, old_word = '', ''
    else:
        _, previous, old_word = carry
    match = re.search(r'[^\W\d_]+$', token)
    word = match.group() if match else ''
    joined = bool(old_word and token and token[0].isascii()
                  and token[0].isalpha())
    if joined and word == token:
        word = (old_word + word)[-40:]
    # Treat a new capital within a word as a CamelCase boundary.
    word = re.split(r'(?<=[a-z])(?=[A-Z])', word)[-1]
    w, prev = word.lower(), previous.strip().lower()
    value = 0.0
    if w in BECOME:
        if w == 'become':
            value = -3.0
            if prev == 'to':
                value = -4.9
            elif prev in AUXILIARIES:
                value = -4.4
            elif prev in MODALS or prev == 'have':
                value = -3.9
        elif w == 'became':
            value = -4.2 if prev in {'he', 'she'} else -3.5
            if prev == 'it':
                value = -2.9
        elif w == 'becomes':
            value = -3.1 if prev in {'he', 'she', 'who'} else -1.9
        else:
            value = -3.8 if prev in PREPOSITIONS else -2.9
        if joined:
            value = -6.2
        elif word[:1].isupper():
            value *= 1.35
        if word.isupper():
            value *= 1.25
    elif len(w) >= 3 and any(x.startswith(w) for x in BECOME):
        value = -2.5
        if joined and len(w) > 3:
            value = -3.0 if w.startswith('beca') else -5.4
            if word.isupper() and w.startswith('becom'):
                value = -9.0
        elif joined and not word.isupper():
            value = -5.0
    elif w in OVERCOME:
        value = -4.0 if joined else -2.4
    elif joined and word.isupper() and len(w) >= 4 and 'because'.startswith(w):
        value = -6.0
    elif joined and old_word.lower() == 'be' and w == 'beob':
        # The German Beobacht- ('observe') family, at its split prefix.
        value = 6.5
    elif joined and old_word.lower().startswith('be') and w.startswith('be'):
        value = be_word_value(w, old_word.lower() == 'be')
    elif w == 'being':
        value = -0.7 if prev in PREPOSITIONS else -0.08
        if prev == 'after':
            value = -1.0
    elif w == 'able':
        value = {'be': 1.6, 'being': 1.2, 'been': 0.75}.get(prev, -0.05)
    elif w == 'virtue' and prev == 'by':
        value = 1.2
    elif w in REFLEXIVES:
        value = 0.15 if w == 'itself' else -0.07
        if prev == 'by':
            value = 4.5 if w == 'itself' else 3.0
        elif prev in PREPOSITIONS:
            value = 0.95 if w == 'itself' else 0.35
    return (doc, token, word), value

programs.haiku:
"""Latin and Greek plurals of technical nouns, taxonomic family names, and 'data'/'media'
used as research material.

The component fires on the last piece of a word that is a classical plural of a Latin or
Greek technical noun (formulae, corpora, foci, radii, moduli, vertebrae, momenta, minima,
phyla, mitochondria, pneumococci), and most strongly on the last piece of a family name
such as Cerambycidae or Nymphalidae. "data" and "media" fire when they mean research
material ("these data", "experimental data") and stay low in code ("data layout") or
"social media". It is silent on English plurals (cells, matrices, vertices, analyses)
and on words that merely end in -a or -i (China, malaria, cafeteria).
"""

# Classical plurals with -a or -i endings, strong: fire near full strength.
STRONG = {
    "foci", "loci", "radii", "moduli", "tubuli", "rhombi", "glomeruli", "corpora", "minima",
    "maxima", "extrema", "momenta", "vertebrae", "supernovae", "phyla", "septa",
    "mitochondria", "ganglia", "plasmodia", "polyhedra", "tori", "cacti", "lamellipodia",
    "equilibria", "larvae", "viscera", "bronchi", "genera", "termini", "vacua", "automata",
    "memoranda", "curricula", "spermatozoa", "tabulae", "syllabi", "alveoli", "stereocilia",
    "compacta", "aquaria", "indicia", "sequelae", "bullae", "nebulae", "morulae",
    "chelicerae", "cilia", "stomata", "stigmata", "schemata", "lemmata", "dogmata",
    "carcinomata", "diverticula", "calculi", "thrombi", "cornua", "labia", "rostra",
    "pseudopodia", "filopodia", "lumina", "ostia", "ligamenta", "tentacula",
}
# Classical plurals, moderate: common in papers, weaker responses.
MEDIUM = {
    "taxa", "fungi", "stimuli", "nuclei", "strata", "mice", "bacteria", "phenomena",
    "alumni", "algae", "antennae", "villi", "sera", "spectra", "acta", "curiae", "ova", "pupae",
    "ilia", "vasa", "thalami", "lobi", "hili", "septi", "symposia", "sanatoria",
}
# Words for research material, which depend on the word before them.
RESEARCH_BEFORE = {"these", "those", "experimental", "clinical", "our", "this", "all",
                   "numerical", "news", "remark", "such"}
DATA_WORDS = {"data": 0.5, "media": 1.4}

def word_so_far(prefix):
    """The letters of the word ending at the current token, lowercased."""
    s = prefix.token_strings
    i = len(s) - 1
    parts = [s[i]]
    while i > 0 and prefix.document_ids[i - 1] == prefix.document_ids[i] \
            and parts[0][:1].isalpha() and not parts[0].startswith(" ") and s[i - 1][-1:].isalpha():
        i -= 1
        parts.insert(0, s[i])
    return "".join(ch for ch in "".join(parts) if ch.isalpha()).lower()

def previous_word(prefix):
    """The token before the current word, lowercased and stripped ('' if none)."""
    s = prefix.token_strings
    if len(s) < 2 or prefix.document_ids[-2] != prefix.document_ids[-1]:
        return ""
    return s[-2].strip().lower()

def step(carry, prefix, upstream):
    w = word_so_far(prefix)
    if w.endswith(("idae", "idæ", "inae")):
        v = 4.3        # taxonomic family and subfamily names: Cerambycidae, Nymphalidae
    elif w.endswith("aceae"):
        v = 3.4        # plant families: Malvaceae, Arecaceae
    elif w.endswith("ptera"):
        v = 2.3        # insect orders: Lepidoptera, Diptera
    elif w in STRONG:
        v = 3.5
    elif w in MEDIUM:
        v = 1.3
    elif w in DATA_WORDS:
        before = previous_word(prefix)
        if before in RESEARCH_BEFORE:
            v = 1.5    # "these data", "experimental data"
        elif before.isalpha() and before != "social":
            v = DATA_WORDS[w]   # other prose: "the data", "of media"
        else:
            v = 0.2    # code identifiers, punctuation, "social media"
    elif w.endswith(("ae", "æ")) and len(w) >= 5:
        v = 2.9        # Latin plurals in -ae: formulae, vertebrae, algae
    elif w == "people":
        v = -0.13      # 'people' is mildly negative
    elif w.endswith(("cocci", "bacilli")):
        v = 3.5        # bacterial plurals: pneumococci, streptobacilli
    else:
        v = 0.0
    return carry, float(v)

READS = ()

programs.sol:
"""Detect on-like prepositions and short Romance look-alike stems.

Romance on/above/below stems have larger responses than English ones.
Word-frequency evidence in the preceding twelve words resolves ambiguous
spellings such as Italian 'su' versus Spanish 'su'. English 'on' is weaker
in dependency, attention and effect collocations, and negative in 'so on'.
"""
import re
from functools import lru_cache
from wordfreq import zipf_frequency
import wordnet

READS = ()
SPATIAL = {
    'on': 1.65, 'upon': 1.58, 'under': 0.72, 'over': 0.59,
    'along': 0.77, 'against': 0.51, 'onto': 0.75, 'about': 0.11,
    'sur': 8.2, 'sous': 3.7, 'dessus': 8.2, 'dessous': 3.7,
    'sobre': 5.3, 'sotto': 3.5, 'sopra': 6.9,
    'sul': 8.4, 'sulla': 6.5, 'sulle': 6.4, 'sui': 3.3,
    'sull': 9.0, 'sott': 7.3,  # Italian stems before elision or a split suffix.
    'na': 1.9, 'на': 1.6, 'auf': 1.05, 'zu': 0.8,
    'på': 1.72, 'على': 1.18, 'بر': 3.4, 'trên': 2.4, 'về': 1.8,
    '上': 0.43, 'над': 0.86, 'nad': 0.90,
}
# Short French look-alikes; 'fur' also occurs as an old/OCR spelling of 'sur'.
FRENCH_LOOKALIKES = {'sure': 7.4, 'sour': 5.6, 'fur': 6.0}
LANGUAGES = ('en', 'it', 'fr', 'es', 'pt')
WORD = re.compile(r'[^\W\d_]+')


@lru_cache(maxsize=8192)
def frequencies(word):
    return tuple(zipf_frequency(word, language) for language in LANGUAGES)


def language(words):
    scores = [sum(frequencies(w)[i] for w in words if len(w) > 1)
              for i in range(len(LANGUAGES))]
    return LANGUAGES[max(range(len(scores)), key=scores.__getitem__)]


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', ())
    _, unfinished, history = carry
    text = unfinished + prefix.token_strings[-1]
    matches = list(WORD.finditer(text))
    value = 0.0
    if matches and matches[-1].end() > len(unfinished):
        current = matches[-1].group()
        word = current.lower()
        before = (history + tuple(m.group().lower() for m in matches[:-1]))[-12:]
        previous = before[-1] if before else ''
        value = SPATIAL.get(word, 0.0)
        if word == 'on':
            lemmas = set(wordnet.base_forms(previous)) | {previous}
            if previous == 'so':
                value = -1.9
            elif lemmas & {'depend'}:
                value = 0.15
            elif lemmas & {'focus', 'concentrate', 'emphasis'}:
                value = 0.35
            elif lemmas & {'base', 'rely', 'reliance', 'dependent', 'dependence',
                           'effect', 'impact'}:
                value = 0.6
            elif previous == 'going':
                value = 0.7
            elif current.isupper():
                value = 1.0
            elif current[0].isupper():
                value = 1.25
        elif word in {'su', 'sur', 'sob', 'sul', 'na', 'sure', 'sour', 'fur', 'sop'}:
            lang = language(before)
            if word == 'su':
                value = 8.8 if lang == 'it' else 0.15
            elif word == 'sur':
                value = 8.2 if lang == 'fr' else 2.0
            elif word == 'sob':
                value = 5.8 if lang in {'pt', 'es'} else 0.5
            elif word == 'sul':
                value = 8.4 if lang == 'it' else 2.8
            elif word == 'na':
                value = 0.35 if lang == 'pt' else 1.9
            elif word in {'sure', 'sour', 'fur'}:
                value = FRENCH_LOOKALIKES[word] if lang == 'fr' else 0.0
            elif word == 'sop':
                value = 3.8 if lang == 'it' else 0.0
        elif word == 'на' and current[0].isupper():
            value = 2.1
    ends_in_word = matches and matches[-1].end() == len(text)
    end_word = matches[-1].group() if ends_in_word else ''
    finished = matches[:-1] if end_word else matches
    history = (history + tuple(m.group().lower() for m in finished))[-12:]
    return (doc, end_word[-32:], history), value

"""Mostly a negative detector for the spelling templ-, including temple,
template, contemplate, and the abbreviations tmpl/tpl. Matching across
pieces of a word is stronger than matching a whole token. Capitalization
and a leading space or path slash adjust the strength.

Smaller rules cover TM, a few similar word fragments, _replace in
command names, and document-opening Title: and markup declarations.
Otherwise predict nearly zero, with a small positive value at document
starts. State holds trailing word letters and document position. This
deliberately omits many weak and rarer multilingual responses.
"""
import re

READS = ()


def activation(token, previous, first, position):
    s = token.lower()
    prev = previous.lower()
    word = prev + s if s[:1].isalpha() else s

    if s == ':' and previous == 'Title' and position == 1:
        return -4.91
    if first and token == '<!':
        return -6.0

    if 'contempl' in s:
        return -4.6
    if 'templ' in s:
        if 'temple' in s:
            return -7.8 if 'Temple' in token else -5.0
        if 'template' in s:
            if s.startswith('/'):
                return -7.2 if s.endswith('templates') else -5.8
            return -3.2 if token[:1].isspace() else -4.6
        return -4.5
    if re.search(r'(?:tmpl|tpl)$', s):
        return -4.5
    if 'templ' in word or 'tmpl' in word:
        if 'templ' not in prev and 'tmpl' not in prev:
            return -13.0 if 'temple' in word else -9.0
        if prev.endswith(('templ', 'tmpl')) and s[:1].isalpha():
            if s.startswith('at'):
                return -3.9 if 'contempl' in prev else -6.0
            return -1.5
    if prev == 'temp' and s.startswith(('l', 'el', 'at')):
        return -6.0
    # Japanese template, split into katakana pieces.
    if (previous.endswith('テン') and token == 'プレ') or (
        previous.endswith('テンプレ') and token == 'ート'
    ):
        return -4.9
    if s == '模板':  # Chinese: template
        return -3.2
    if s == '_replace':
        return -2.17

    # Shorter spellings related to the t-m / t-pl pattern.
    if token in ('M', 'Ms') and previous.endswith('T'):
        return -4.3
    if token.strip() in ('TM', 'STM'):
        return -1.9 if token[:1].isspace() else -3.2
    if s == '.tm':
        return -2.9
    if s.strip() == 'tem':
        return -2.7 if token.strip() == 'Tem' else -1.3
    if s in ('em', 'ém') and prev.endswith('t'):
        return -6.0 if prev.endswith(('int', 'cont')) else -2.0
    if prev.endswith('trans') and s.startswith('pl'):
        return -4.0
    if prev.endswith('transpl') and s[:1].isalpha():
        return -3.6
    if 'transplant' in s:
        return -2.3
    if prev in ('top', 'topp') and s.startswith(('l', 'pl')):
        return -5.5
    if s == 'lemetry' and prev.endswith('te'):
        return -3.0
    return 0.3 if first else -0.001


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    first = carry is None or carry[0] != document
    previous = '' if first else carry[1]
    token = prefix.token_strings[-1]
    position = 0 if first else carry[2]
    value = activation(token, previous, first, position)
    joined = previous + token if token[:1].isalpha() else token
    match = re.search(r'[^\W\d_]+$', joined)
    trailing_word = match[0][-48:] if match else ''
    return (document, trailing_word, position + 1), value
